programs.sol:
"""Approximate an underscore-centered punctuation response.

Underscores after spaces, attribute dots, calls, or path slashes respond most;
identifier/subscript separators and long underline rules respond less. Asterisks
have smaller responses, reduced in block comments. A spaced caret also responds.
The constants summarize training activations for these readable text patterns.
Other tokens predict zero. State tracks only the previous token, line beginnings,
and block comments, and resets between documents.
"""
READS = ()

# Prefix punctuation: response for one underscore, then two underscores.
UNDERSCORE_PREFIXES = {
    '.': (2.1, 2.1),        # Private/special member access.
    '/': (1.55, 2.6),       # Underscore-prefixed path segments.
    '(': (2.95, 2.05),      # Call arguments.
    ',': (2.3, 1.8),        # Comma-separated names.
    '\\': (0.65, 0.65),   # Escaped underscore.
    '$': (0.88, 0.88),      # Dollar-prefixed names.
}


def underscore_response(s, previous):
    start = s.index('_')
    end = start
    while end < len(s) and s[end] == '_':
        end += 1
    before, after = s[:start], s[end:]
    n = end - start
    if '_' in after:        # Several underscore runs in one punctuation token.
        return 1.8
    if after:
        if before == ' ':
            return 2.0
        if after.startswith(('{', '\\')):
            return -0.08
        return 0.4 if n == 1 else 0.2
    if n >= 3:
        return 1.2 + 4.0 / n if before == ' ' else 0.6
    if before == ' ':
        if n == 2:
            return 3.75
        return 3.76 if previous == ' _' else 4.5
    if not before:
        if n == 2:
            return 0.9 if previous and set(previous) == {'_'} else 1.68
        word = previous.strip()
        if len(word) == 1 and word.isalpha():
            return 0.2 if word.isupper() else 0.33
        if word.isalpha():
            return 0.4 if word.isupper() else 0.57
        return 0.2 if word.endswith('}') else 0.5
    if before == '.' and n == 1:
        if previous.strip().lstrip('(') in ('self', 'this'):
            return 2.57
    if before in UNDERSCORE_PREFIXES:
        return UNDERSCORE_PREFIXES[before][n - 1]
    if before.strip() == '(':
        return 2.55 if n == 1 else 2.0
    if before in (')', '}', ']'):
        return 0.45
    if '"' in before or "'" in before:
        return 0.72 if before == "'" else 1.35
    return 1.65


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, line_start, comment = '', True, False
    else:
        _, previous, line_start, comment = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if '_' in s and not any(c.isalnum() for c in s):
        value = underscore_response(s, previous)
    elif s == ' *':
        if comment:
            value = 0.02 if line_start else 0.29
        else:
            value = 0.5 if line_start else 0.76
    elif s in ('*', ' **', '**', ' ^', '^{'):
        value = {'*': 0.16, ' **': 0.2, '**': -0.12,
                 ' ^': 1.37, '^{': -0.13}[s]
    # Both actual and escaped newlines can describe source-code lines.
    if '/*' in s:
        comment = True
    if '*/' in s:
        comment = False
    line = s.replace('\\n', '\n').rsplit('\n', 1)
    if len(line) == 2:
        line_start = not line[-1].strip()
    elif s.strip():
        line_start = False
    return (doc, s, line_start, comment), value

programs.luna:
"""Predict bursts on underscore-started names and a smaller asterisk cue."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    # A space before an underscore commonly starts a private or throwaway name.
    if token.startswith(" __"):
        return None, 4.2
    if token.startswith(" _"):
        return None, 4.58

    # Punctuation can be attached to the start of an underscore-name.
    mark = token.find("_")
    if mark > 0 and all(
        not char.isalnum() and char != "_" for char in token[:mark]
    ):
        return None, 2.2

    # A doubled underscore at the end often marks a special name or separator.
    if token.endswith("__"):
        return None, 1.75

    # A separated asterisk is a smaller, less consistent code/math cue.
    if token == " *":
        return None, 0.32
    if token == "*":
        return None, 0.15
    return None, 0.0

"""Pick out technical statements about joining, mounting, or supplying parts."""
READS = ()

# Physical and electrical objects that mark an engineering context.
TECHNICAL_OBJECTS = {
    "apparatus", "device", "system", "component", "part", "member",
    "machine", "motor", "engine", "shaft", "frame", "housing",
    "pipe", "hose", "duct", "valve", "inlet", "outlet", "circuit",
    "terminal", "wire", "cable", "signal", "voltage", "current",
    "battery", "cell", "electrode", "capacitor", "resistor", "conductor",
    "generator", "compressor", "pump", "tank", "sensor", "robot",
    "vehicle", "transmission", "bearing", "piston", "cylinder", "tube",
    "air", "fluid", "pressure", "feed", "supply", "converter",
    "processor", "assembly", "network", "hose", "connector", "gear",
}
RELATIONS = {
    "connected", "mounted", "fed", "supplied", "supply", "supplies",
    "连接",
}
FOLLOWERS = {"to", "through", "by"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history = ()
    else:
        history = carry[1]

    technical_context = any(token in TECHNICAL_OBJECTS for token in history)
    recent_relation = bool(history and history[-1] in RELATIONS)

    if word in RELATIONS and technical_context:
        value = -0.62
    elif word in FOLLOWERS and recent_relation and technical_context:
        value = -0.40
    else:
        value = 0.0

    history = (history + (word,))[-8:]
    return (document, history), value

programs.sol:
"""A local spelling feature, dominated by 'art' and short -art syllables.

Isolated art is strongest; part/heart and longer art forms are weaker; start
is nearly inactive. Case and leading whitespace or punctuation calibrate the
response. Small
extensions cover nearby r-consonant syllables and art/intelligence terms in
other scripts. This program does not attempt to model contextual variation.
"""
import string

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip(string.punctuation)
    w = word.lower()
    boundary = token[:1].isspace() or token[:1] in string.punctuation
    value = 0.0
    if w == 'art':
        if boundary:
            value = 5.7 if word.istitle() else 4.95
        else:
            value = 5.35 if word.istitle() else 6.3
    elif 'art' in w:
        before, after = w.split('art', 1)
        if 'start' in w or any(s in w for s in
                ('earth', 'particul', 'partner', 'participant', 'partial')):
            value = 0.05
        elif any(s in w for s in ('depart', 'apartment', 'particip')):
            value = 0.25
        elif not after or after == 's':
            if before in ('p', 'ap', 'he'):
                value = 1.2 if after else 1.85
            elif not before:
                value = 3.5 if boundary else 5.3
            elif before == 'qu':
                value = 2.8
            elif before == 'c':
                value = 3.8
            elif len(before) > 2 or any(c in 'aeiou' for c in before):
                value = 1.0
            else:
                value = 4.8
        elif w.startswith('part'):
            value = 1.0
        elif before in ('qu', 'he', 'sp', 'w') or len(before) > 2:
            value = 0.5
        elif w.startswith(('arth', 'artific', 'martial', 'cartoon')):
            value = 0.7
        elif w.startswith(('artic', 'artist')):
            value = 1.4
        else:
            value = 2.2 if len(after) <= 3 else 1.0
    elif w in ('rt', 'ert', 'irt', 'urt', 'ort', 'bert', 'ard', 'ards', 'ardi'):
        value = 0.8
    elif w in ('court', 'hurt', 'hard', 'harm') or w.startswith('card'):
        value = 1.5 if w == 'hard' else 1.0
    elif w == 'arm' and not boundary:
        value = 0.7
    elif w.startswith('intellig') or w in ('sharp', '智能', '智', '智慧'):
        value = 0.6 if w == 'intelligence' else 1.3
    elif '艺术' in w or '藝術' in w:
        value = 3.3
    elif w in ('艺', '藝', '術') or w.startswith('искусств'):
        value = 1.3
    elif w == 'арт':
        value = 5.4
    elif w in ('карт', 'ارت'):
        value = 2.7
    elif w == 'парт':
        value = 1.9
    elif w in ('ート', 'パート', 'アート'):
        value = 1.5
    return None, float(value)

programs.luna:
"""Use the current token's spelling as a rough cue for the component.

A token that reads "art" gets a large prediction. Other tokens ending in
"art" get a smaller one, except familiar lookalikes such as "start", "heart",
and "apart". "part" gets a modest prediction; other appearances of "art"
get only a small one. This is a spelling heuristic, not a word-meaning test.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold().rstrip(".,:;!?\\\"'")

    if word == "art":
        return None, 5.3
    if word == "part":
        return None, 1.8
    if word.endswith("start"):
        return None, 0.0
    if word in ("heart", "apart"):
        return None, 1.9
    if "particular" in word:
        return None, 0.0
    if word.endswith("art"):
        return None, 4.5
    if "art" in word:
        return None, 0.45
    return None, 0.0

programs.sol:
"""Recognize test-related words and identifiers, not the activity of testing.

The response is strongest for a bare 'test' in names or paths, weaker for
plurals and inflections. Spacing, case, and a leading dot change its size.
Other identifier-shaped tokens get a weak negative background response,
particularly longer path members and capitalized continuations of a word.
Common filename extensions get a small positive offset, and the reasoning
opener gets a small negative one. These are background corrections, not
test detection. The only state is the preceding character, reset at document
boundaries.
"""
import re

READS = ()

# Testing tools and token fragments of testing-related identifiers.
TEST_NAMES = {'pytest', 'unittest', 'httptest', 'ptest', 'ittest'}
FILE_EXTENSIONS = {
    '.js', '.ts', '.py', '.go', '.java', '.json', '.txt', '.md', '.html',
    '.css', '.cpp', '.c', '.h', '.rs', '.sh',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    joined = bool(previous) and previous[-1].isalpha()
    word = token.lstrip(' \t\r\n./_-(<[{@"\'=:\\')
    lower = word.lower()
    spaced = bool(token) and token[0].isspace()
    value = -0.001
    if lower == 'test':
        if spaced:
            value = -1.14 if word == 'Test' else -1.03
            if previous and previous[-1].isspace():
                value -= 0.10
        elif token.startswith(('.', '/Test')):
            value = -1.55
        elif token.startswith('-'):
            value = -1.17
        elif token.startswith(('(', '[', '<', '@', '=', ':')):
            value = -0.9
        else:
            value = -1.36
            if token == 'test' and joined:
                value = -1.12
            elif token == 'Test' and previous and previous[-1].isspace():
                value = -1.13
    elif lower == 'tests':
        if spaced:
            value = -0.8
        elif word == 'tests' and token == word:
            value = -1.3
        else:
            value = -1.05
    elif lower in ('tested', 'testing', 'tester', 'testers'):
        value = -0.6 if spaced else -0.78
        if word == 'Tester':
            value = -1.4
        elif token.startswith('/'):
            value = -1.1
    elif lower in TEST_NAMES:
        value = -1.0
        if lower in ('ptest', 'httptest'):
            value = -1.4
    elif 'Test' in word or re.match(r'test[A-Z]', word) or lower == 'testcase':
        value = -0.7 if not spaced else -0.5
    elif lower in ('测试', 'тест'):
        value = -0.65
    elif token == '<think>':
        value = -0.19
    elif token in FILE_EXTENSIONS:
        value = 0.07
    elif word.isascii() and word.isalpha():
        size = len(word)
        if token.startswith(('/', '_')):
            value = -0.025 if size <= 3 else -0.08 if size <= 5 else -0.15
        elif token.startswith('.'):
            value = -0.01 if size <= 3 else -0.065
        elif token.startswith('-'):
            value = -0.025 if size <= 5 else -0.08
        elif token == word and word.istitle():
            value = -0.11 if joined and size >= 3 else 0.01
        elif re.search(r'[a-z][A-Z]', word):
            value = -0.06
    return (doc, token[-1:]), value

"""Approximate a negative 'tr' spelling/word-family detector.

Bare 'tr' fragments fire most strongly, especially capitalized ones.
Word families have unequal strengths: track/trade are strong; true,
try, tree, and most words using the productive prefix trans- are weak.
It also follows a split tr-initial word onto its next token. A few
cross-script spellings and translations of tr words are included.
Strengths are fitted averages; finer lexical offsets are left unexplained.
"""
import re

READS = ()
WORD = re.compile(r'[A-Za-z]+$')
LEADING_PUNCTUATION = "._-/(:\"'`"


def response(raw, previous=''):
    text = raw.lstrip()
    # Chinese: training, trade, treatment/travel, and pursuit/tracking.
    if text in ('训练', '训', '訓', '訓練'):
        return -2.1
    if text in ('贸易', '貿易', '国际贸易'):
        return -2.8
    if text == '交易':
        return -2.1
    if text in ('治疗', '治療', '旅行', '旅'):
        return -1.0
    if text == '追':
        return -3.7
    if text == '跟踪':
        return -2.3
    # Japanese/Korean phonetic fragments related to tr; Russian 'tr'.
    phonetic = {
        'トレ': -3.6,
        'トリ': -2.4,
        'ト': -0.6,
        '트': -0.5,
    }
    if text in phonetic:
        return phonetic[text]
    if text.lower() == 'тр':
        return -2.1
    word = text.lstrip(LEADING_PUNCTUATION).lower()
    if word == 'tr':
        value = -3.3 if raw[:1].isspace() else -2.6
        if not raw[:1].isspace() and previous.endswith(('<', '</')):
            value = -4.1
        if text.lstrip(LEADING_PUNCTUATION) == 'Tr':
            value -= 1.3
        elif text.startswith(('-', '/', '_', '.')):
            value -= 1.5
        return value
    if not word.startswith('tr'):
        if word.endswith('tr') and not word.endswith('str'):
            return -0.6
        return -0.04 if 'tr' in word else 0.0
    if word.startswith(('tree', 'tres', 'très', 'trois', 'trans')):
        if word.startswith('transact'):
            return -1.1
        if word.startswith('transport'):
            return -0.6
        return -0.15
    if word.startswith((
        'tradition', 'traffic', 'trend', 'tripl', 'trigger', 'trademark'
    )):
        return -0.5
    if word.startswith(('true', 'try', 'truly', 'tries', 'tried')):
        if word.startswith(('trying', 'tried')):
            return -0.55
        return -0.55 if text.startswith('True') else -0.15
    if word.startswith(('track', 'trade', 'trading', 'trace', 'trail', 'trap')):
        return -2.7 if word.startswith(('track', 'trade', 'trading')) else -2.4
    if word.startswith((
        'train', 'trial', 'trait', 'treat', 'trust', 'trim', 'truck'
    )):
        return -1.35 if word.startswith('treatment') else -1.9
    if word.startswith('trip') and not word.startswith('tripl'):
        return -1.5
    if word in ('tra', 'tri', 'tro', 'trou', 'trad', 'trig', 'tray'):
        return -1.9
    return -1.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    value = response(raw, previous)
    continuation = raw[:1].isascii() and raw[:1].isalpha()
    if continuation and previous.lower() == 'tr':
        value = response(previous + raw)
    match = WORD.search(raw)
    previous = match.group() if match else raw.rstrip()
    return (doc, previous), float(value)

programs.luna:
"""A cautious spelling-based approximation for 'tr' responses."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    word = token.strip(" \t\r\n.,:;!?()[]{}\"'")
    if "tr" not in word:
        return None, 0.0
    if word == "tr":
        return None, -1.3
    if word.startswith("tr"):
        return None, -0.8
    return None, -0.45

programs.haiku:
"""Question-inversion detector (layer 0 MLP, component 585).

This component goes strongly negative on the auxiliary verb or copula that comes right
after an interrogative wh-word, the inverted verb of a direct question:
"what IS the", "how ARE you", "how DOES it", "why DID", "where ARE", "what'S your".
It is near zero for relative "which" ("the tool which IS"), and only mildly negative for
"who" ("the man who HAS"). Modal verbs ("how CAN", "what WILL") are a bit weaker.
Everywhere else it predicts 0.
"""

READS = ()

# how strongly each wh-word, directly before the verb, drives the component
WH_STRENGTH = {"what": 6.5, "how": 6.5, "why": 6.5, "where": 5.0, "when": 3.0, "who": 1.0, "whatever": 2.5}
# the verbs that invert after a wh-word
INVERTING_VERBS = {
    "is", "are", "was", "were", "am", "s", "be", "should", "would", "could", "can", "will",
    "shall", "may", "might", "must", "does", "do", "did", "has", "have", "had",
}
MODALS = {"can", "could", "will", "would", "may", "might", "shall", "must"}
PUNCTUATION = " .,!?;:\"'“”‘’()[]\n"


def _word(token):
    return token.strip(PUNCTUATION).lower()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    if len(tokens) < 2 or docs[-1] != docs[-2]:
        return None, 0.0
    verb = _word(tokens[-1])
    strength = WH_STRENGTH.get(_word(tokens[-2]))
    if strength is None or verb not in INVERTING_VERBS:
        return None, 0.0
    if verb in MODALS:
        strength *= 0.75
    elif verb == "s":
        strength *= 0.6
    return None, -strength

programs.luna:
"""Predict a negative activation for common English question-word + auxiliary
phrases, including the short contracted forms of auxiliaries."""

READS = ()

QUESTION_WORDS = {"what", "why", "how", "where", "when"}

AFTER_QUESTION_WORD = {
    "is": -5.8, "are": -6.5, "was": -5.5, "were": -2.5, "am": -4.0,
    "do": -6.0, "does": -6.0, "did": -5.5,
    "can": -5.5, "could": -5.0, "will": -4.0, "would": -4.5,
    "shall": -2.0, "should": -5.5,
    "have": -2.0, "has": -3.0, "had": -2.0,
    "s": -3.9, "’s": -3.9, "d": -1.0, "’d": -1.0,
}

EDGE_PUNCTUATION = " \t\r\n.,?!:;()[]{}\"'`*_~<>"


def _word(token):
    return token.strip().lower().strip(EDGE_PUNCTUATION)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = None if carry is None or carry[0] != document else carry[1]
    word = _word(prefix.token_strings[-1])

    value = 0.0
    if previous in QUESTION_WORDS:
        value = AFTER_QUESTION_WORD.get(word, 0.0)

    return (document, word), float(value)

programs.sol:
"""Approximate the strong 'ion' spelling response and related lion words.

Bare 'ion' is weaker after t/s than after r/l/b/m. Suffix forms have
separate gains, and ordinary longer words dilute the response. A few
recognizable words, names, Romance endings, and Chinese lion/ion forms
are calibrated separately. Everything else predicts zero: the many
small background responses are deliberately not a vocabulary lookup.
"""
import math

READS = ()

# Gain and minimum response for common suffix fragments.
ION_FORMS = {
    'ion': (1.0, 0.0),
    'ions': (0.9, 0.0),
    'ione': (0.75, 0.0),
    'ioni': (0.7, 1.5),
    'ional': (0.45, 0.65),
    'iones': (0.45, 0.8),
    'ionate': (0.5, 0.0),
}


def onset_strength(left):
    if not left:
        return 2.5
    if not left[-1].isalpha():
        return 3.3
    if left.endswith('t'):
        return 0.6
    if left.endswith('ss'):
        return 0.6
    if left.endswith('s'):
        return 1.2
    if left.endswith('sc'):
        return 4.5
    if left.endswith('c'):
        return 1.7
    if left.endswith('z'):
        return 2.1
    if left.endswith('g'):
        return 2.6
    if left.endswith('v'):
        return 3.2
    if left.endswith('x'):
        return 4.0 if len(left.strip()) == 1 else 1.6
    if left.endswith('un'):
        return 2.0
    if left.endswith(('r', 'l', 'b')):
        return 4.9
    if left.endswith('m'):
        return 4.4
    return 3.9


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw_word = token.strip(" \t\r\n-_/.\"'")
    word = raw_word.lower()
    left = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2] and
            token and token[0].isalpha()):
        left = prefix.token_strings[-2].lower()
    plain = word.replace('ó', 'o')
    value = 0.0
    if plain in {'lion', 'lions'}:
        if word.endswith('s'):
            value = 3.9 if raw_word.istitle() else 3.6
        elif token.startswith(' '):
            value = 4.9 if raw_word.istitle() else 4.25
        else:
            value = 3.2
    elif plain in {'union', 'unions'}:
        value = 1.0 if word.endswith('s') or raw_word.istitle() else 1.35
    elif plain in {'onion', 'onions'}:
        value = 1.8 if word.endswith('s') else 1.5
    elif raw_word in {'Dion', 'Marion', 'Orion', 'Zion'}:
        value = 3.0 if raw_word == 'Dion' else 1.85
    elif plain == 'ion' and plain != word:
        value = 1.15
    elif plain == 'ionic':
        value = 2.6 if token[0].isspace() or raw_word.istitle() else 4.2
    elif plain.startswith('ion'):
        gain, minimum = ION_FORMS.get(plain, (0.3, 0.0))
        value = max(gain * onset_strength(left), minimum)
        if plain == 'ions' and left.endswith('un'):
            value = 2.9
    elif plain.endswith('pion'):
        value = 0.85
    elif 'ion' in plain:
        before, _, after = plain.partition('ion')
        value = onset_strength(before) * math.exp(-0.65 * len(before))
        value *= math.exp(-0.25 * len(after))
        if len(before) >= 3 and token.startswith(' '):
            value *= 0.25
        if plain.endswith(('ation', 'ations', 'acion', 'aciones', 'azione')):
            value = 0.0
    elif plain in {'ison', 'idon', 'yon', 'iot', 'iotic', 'thon', 'illon'}:
        value = 0.65
    elif word in {'狮', '獅'}:
        value = 3.9
    elif word in {'狮子', '獅子'}:
        value = 2.6
    elif word in {'ão', 'ón'}:
        value = 0.45
    elif word == 'ião':
        value = 1.8
    elif word in {'leon', 'león', 'lyon'}:
        value = 0.8
    elif word in {'离子', '離子'}:
        value = 2.4
    return None, float(value)

