programs.sol:
"""Model negative spikes on two-to-six-hash Markdown heading markers.

Heading depth determines the response. It is strongest at the very start of a
document, then weakens approximately with log position. Indented markers are
weaker. The first content token after a level-two or level-three marker gets a
positive echo. Single hashes get a small positive response; empty headings
(markers ending in whitespace) and long separator rules are ignored.
"""
import math

READS = ()
# Hash count: (at document start, intercept, log-position slope, indent adjustment).
HEADINGS = {
    2: (-4.22, -0.43, 0.071, 0.04),
    3: (-6.27, -1.36, 0.136, 0.23),
    4: (-10.01, -4.88, 0.400, 0.30),
    5: (-10.93, -5.33, 0.291, 1.25),
    6: (-8.97, -4.58, 0.165, 0.0),
}


def marker(text):
    stripped = text.strip()
    if stripped and set(stripped) == {'#'} and not text[-1].isspace():
        return len(stripped)
    return 0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous_depth = 0, 0
    else:
        position, previous_depth = carry[1] + 1, carry[2]
    text = prefix.token_strings[-1]
    depth = marker(text)
    value = 0.0
    if depth in HEADINGS:
        start, intercept, slope, indent = HEADINGS[depth]
        if position == 0:
            value = start * (0.45 if text[0].isspace() else 1.0)
        else:
            value = intercept + slope * math.log1p(position)
            if text[0].isspace():
                value += indent
    elif depth == 1 and not text[0].isspace():
        value = 0.05
    elif not depth and previous_depth in (2, 3):
        word = text.strip()
        value = (0.12 if previous_depth == 2 else 0.20)
        if not word or not word[0].isalpha():
            value = (0.24 if previous_depth == 2 else 0.48)
        if position == 1:
            value += (0.25 if previous_depth == 2 else 1.20)
    return (doc, position, depth), float(value)

programs.haiku:
"""Markdown heading markers, for layers.0.mlp.down_proj:590.

This component is a "heading marker" detector with a negative sign. Its activation is
strongly negative on a run of '#' characters that opens a Markdown heading:

  * at the start of a line, the more hashes, the more negative: '##' about -0.1,
    '###' about -0.7, '####' about -2.8, '#####' about -3.9 (deeper runs of 6 or more
    are weaker, about -1);
  * right after a document boundary (the <|endoftext|> token, or the first token of a
    row), a '##' or '###' heading is very negative, about -4.5;
  * the first word after a '###'-or-deeper heading marker is slightly positive (+0.3);
  * separator decorations ('**', '///', and runs of '=' or '/') are mildly negative
    (-0.3).

Everything else is predicted as 0. The program explains about 18% of the variance on
training text. The remaining variance is spread over ordinary tokens with small,
token-specific values (about 0.05 std) that have no simple description.
"""

READS = ()

# Activation of a heading marker by its number of '#', when it starts a line.
LINE_START_VALUE = {2: -0.1, 3: -0.7, 4: -2.8, 5: -3.9}
DEEP_HEADING_VALUE = -1.0       # 6 or more hashes in one token
DOCUMENT_START_VALUE = -4.5     # a '##' or '###' heading right after a document boundary
WORD_AFTER_HEADING = 0.3        # the heading's first word
SEPARATOR_VALUE = -0.3          # '**', '///', runs of '=' or '/'


def hash_count(token):
    """How many '#' a token is made of, or 0 if it is not a run of '#' alone."""
    body = token.strip()
    return len(body) if body and set(body) == {"#"} else 0


def is_separator(token):
    """A decoration token: bold markers, '///', and runs of '=' or '/' (no leading space)."""
    if token in ("**", "///", " ///"):
        return True
    body = token.strip()
    return len(body) >= 3 and set(body) <= set("=/") and not token.startswith(" ")


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t]
    previous = prefix.token_strings[t - 1] if t > 0 else ""
    after_boundary = t == 0 or previous == "<|endoftext|>"
    at_line_start = after_boundary or previous.endswith("\n")
    n = hash_count(token)

    if n >= 2 and (at_line_start or token.startswith(" ")):
        if after_boundary and n <= 3:
            return carry, DOCUMENT_START_VALUE
        if n >= 6:
            return carry, DEEP_HEADING_VALUE
        return carry, LINE_START_VALUE.get(n, DEEP_HEADING_VALUE)
    if hash_count(previous) >= 3 and token.startswith(" "):
        return carry, WORD_AFTER_HEADING
    if is_separator(token):
        return carry, SEPARATOR_VALUE
    return carry, 0.0

"""Light detector. The component responds negatively to the concept of light. The word 'light'
(and 光, Chinese for light) gives the strongest response; compounds such as sunlight, lights
and lighting a somewhat weaker one; and light words in other languages, highlights, optics,
photos, sunshine, brightness and darkness a weaker one still. Other tokens give zero."""

READS = ()

LIGHT = {"light", "光"}
NOT_LIGHT = ("slight", "flight", "delight", "plight", "twilight")   # contain 'light', not about light
WEAK_LIGHT = ("lightly", "lightweight", "lightning", "lighter", "lighthouse")
FOREIGN = {"свет", "lumière", "luz", "광", "阳光", "灯", "照", "轻", "licht", "icht", "ight", "灯光"}
PHOTO_SUN = ("photo", "phot", "optic", "laser", "sun", "solar", "bright", "dark", "lamp", "glow", "illumin")

def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip().strip("._/(-\"'").lower()
    if w in LIGHT:
        return None, -6.0
    if any(c in w for c in NOT_LIGHT) or w == "sunday":
        return None, 0.0
    if "highlight" in w:
        return None, -2.0
    if "light" in w:
        return None, -1.5 if any(c in w for c in WEAK_LIGHT) else -4.0
    if w in FOREIGN:
        return None, -2.0
    if any(c in w for c in PHOTO_SUN):
        return None, -1.0
    return None, 0.0

