"""A sparse light-and-optics detector for this down-projection component.

It gives a large negative response to the word light (and the Chinese
character for light), with smaller responses to sunlight, photography, and
optics vocabulary. It leaves unrelated tokens at zero.
"""

READS = ()

STRONG_LIGHT = {"light", "光"}
LIGHT_FRAGMENTS = {"elight", "lighting", "lightning"}
LIGHT_ASSOCIATES = {
    "sun", "sunshine", "sunny", "solar", "dark", "optical", "photo",
    "photos", "photograph", "photography", "photographer", "lamp",
    "lamps", "led", "sight", "glare", "glaring", "brightness",
