programs.sol:
"""A mostly lexical detector for 'that' and 'those'.

These words give strong negative responses, especially when capitalized.
A preceding evidence/reporting word or 'so/such that' weakens 'that';
coordination and punctuation strengthen it. Previous-token cues never cross
document boundaries. Related demonstratives, several translations, Chinese
demonstrative prefixes, and reasoning delimiters have smaller responses.

The approximation omits the many weak responses to unrelated tokens.
"""
READS = ()

# Common complementizers / distal demonstratives in other languages.
THAT_WORDS = {
    'что': -0.75, 'dass': -0.78, 'daß': -0.64, 'dat': -0.85,
    'أن': -0.79, 'hogy': -0.54, 'que': -0.14,
    'che': -0.14, 'že': -0.45,
}


# Verbs that introduce evidence or a reported proposition.
SHOWING = set('show shows showed shown note noted see known'.split())
KNOWING_OR_SAYING = set('''
    know knew found find remember understand understood
    say says said saying mention given
'''.split())
REPORTING = set('''
    state states stated suggest suggests suggested indicate indicates indicated
    mentions revealed mean means ensure
'''.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('-—–“\"').lower()
    capitalized = any(c.isupper() for c in token)
    if word == 'that':
        value = -2.72 if capitalized else -1.64
        if not capitalized and not token.startswith(' '):
            value = -2.17
        if not capitalized and token == ' that':
            previous = ''
            if (len(prefix.token_strings) > 1 and
                    prefix.document_ids[-1] == prefix.document_ids[-2]):
                previous = prefix.token_strings[-2].strip().lower()
            if previous == 'such':
                value = -0.85
            elif previous == 'so':
                value = -1.30
            elif previous == 'fact':
                value = -0.95
            elif previous in SHOWING:
                value = -1.10
            elif previous in KNOWING_OR_SAYING:
                value = -1.30
            elif previous in REPORTING:
                value = -1.45
            elif previous == 'and':
                value = -2.39
            elif previous in {'as', 'than', 'except'}:
                value = -2.04
            elif previous == ',':
                value = -2.07
            elif previous and all(c in '.!?;:\n' for c in previous):
                value = -2.45
            else:
                value = -1.72
    elif word == 'those':
        value = -3.85 if capitalized else -3.52
    elif word == 'these':
        value = -0.22
    elif word == 'this':
        value = 0.10 if capitalized else 0.045
    elif word in THAT_WORDS:
        value = THAT_WORDS[word]
    elif token.startswith(('那', '的那')):
        value = -1.63 if '些' in token else -0.90
    elif token.startswith(('这', '這', '的这', '的這')):
        value = 0.32
    elif token == '</think>':
        value = 0.34
    elif token == '<think>':
        value = 0.20
    else:
        value = 0.0
    return None, value

programs.haiku:
"""Component layers.0.mlp.down_proj:593 — a "that / those" detector.

This component is a demonstrative/complementizer word detector. It writes a strong
negative value into the residual stream on the word "that" (and especially "those"),
and is essentially silent on every other token.

Its activation (what this program predicts) is, per token:
  - "those"                         -> about -3.5   (the strongest)
  - sentence-initial "That"/"that"  -> about -2.7   ("That is, ...", "That said, ...")
  - "that" after "such", "fact",
    "so", "show(s)", "showed"       -> about -1.0   (weaker: "such that", "the fact that")
  - any other "that"                -> about -1.7   (complementizer / relative "that")
  - "these"                         -> about -0.2
  - "that" in other languages
    (Russian "что", German "dass",
    Arabic "أن", Hungarian "hogy",
    Chinese "那") -> about -0.8
  - everything else                 -> 0

Words are matched after stripping spaces and lowercasing, so " that", "That" and
"that" all count. The program keeps no state beyond the previous token and
document boundaries, which it reads from the prefix.
"""

READS = ()

PLURAL_DEMONSTRATIVE = {"those"}
FOREIGN_THAT = {"что", "dass", "daß", "أن", "hogy", "那", "那些", "那个"}
WEAK_CONTEXT = {"such", "fact", "so", "show", "shows", "showed"}
SENTENCE_END = (".", "!", "?", "\n", '"', "“", "”")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = prefix.token_strings[-2]
    else:
        before = ""  # first token of a document: a sentence start
    prev = before.strip().lower()

    if word in PLURAL_DEMONSTRATIVE:
        value = -3.5
    elif word == "that" or word == "thats":
        if token.strip()[:1].isupper() or before.strip() == "" or before[-1:] in SENTENCE_END:
            value = -2.7
        elif prev in WEAK_CONTEXT:
            value = -1.0
        else:
            value = -1.7
    elif word == "these":
        value = -0.2
    elif word in FOREIGN_THAT:
        value = -0.8
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Make small predictions for two sparse text cues: nearby negation and contrast.

The high-impact samples include negated phrases and comma-plus-“but” turns,
but broad, full-sized predictions overstate their typical activation. The small
values here are cautious estimates; many phrase-specific exceptions remain.
"""
READS = ()
NEGATORS = {"not", "no", "non", "never", "neither", "nor", "cannot",
            "can't", "without", "nicht", "не", "不", "沒", "无", "未", "tidak"}
PUNCT = ".,;:!?()[]{}\"'`，。；：！？、"


def clean(token):
    return token.strip().lower().strip(PUNCT)


def step(carry, prefix, upstream):
    words = prefix.token_strings
    docs = prefix.document_ids
    if len(words) >= 2 and docs[-1] == docs[-2]:
        if clean(words[-1]) == "but" and words[-2].strip() == ",":
            return None, 0.1
        previous = clean(words[-2])
        negative = (previous in NEGATORS or previous.endswith("n't")
                    or previous.startswith(("non", "un-")))
        if len(words) >= 3 and docs[-1] == docs[-3]:
            earlier = clean(words[-3])
            negative = negative or earlier in NEGATORS
            negative = negative or (
                previous in {"t", "'t", "’t"}
                and earlier.endswith(("n", "is", "was", "were"))
            )
        if negative:
            return None, -0.05
    return None, 0.0

