RISE_DEGREE = {"peak", "peaks", "height", "heights", "raise", "raised", "raising",
               "rise", "rising", "increase", "increased", "above", "more", "very",
               "extreme", "extremely", "large", "level", "levels", "medium",
               "upward", "climb", "elevated", "heavy", "positive", "wide"}


