programs.sol:
"""Approximate a detector of repetition and emphatic punctuation.

Only the current token is read. Question/exclamation marks, repeated letters,
markup, Boolean operators, and long separators/blank runs get positive values.
Most punctuation cues are weakened by newlines. URL introductions also fire.
Other tokens get zero; ordinary doubled letters inside words are not detected.
The gains approximate training averages, not a universal rule about text.
"""
READS = ()


def repetition(char, n, space):
    if char.isascii() and char.isalpha():
        if n == 2:
            return 0.9 if char.lower() in 'hijquvwxyz' else 0.25
        if n == 3:
            return 1.3 if char.lower() in 'im' else 2.4
        return min(7.0, 5.1 + 0.4 * (n - 4))
    if char.isalpha():
        return 0.15 * (n - 1)
    if char in '?!？！':
        return 1.4 if n == 2 else 2.1 if n == 3 else min(5.0, n)
    if char in '^＾\\':
        if char == '\\':
            return 1.3 if n == 2 else 1.1 if n == 3 else 3.5
        return min(4.1, 0.6 * n * (n - 1))
    if char == '*':
        if n == 2:
            return 0.75 if space else 0.6
        if n == 3:
            return 1.1
        return 1.8 if n < 8 else 2.5 if n < 16 else 1.5
    if char == '.':
        return 0.0 if n <= 3 else min(1.6, 0.2 * n - 0.2)
    if char in '-=_#':
        if n == 2:
            return 0.0
        if char == '=' and n == 3:
            return 0.15  # Triple equals is an operator, not a separator.
        return min(1.6 if char == '#' else 1.15, 0.25 * (n - 1))
    if char in '\'"`$':
        return 0.0 if n <= 3 else 2.7
    if char in ')}':
        return 0.2 * (n - 2)
    if char in '([]{<>/':
        return 0.0 if n == 2 else 0.3 if n == 3 else 1.5
    if char == '+':
        return 0.2 if n == 2 else 1.05 if n == 3 else 2.4
    if char == ':':
        return 0.24 if n == 2 else 2.0
    if char in '─━':
        return min(1.2, 0.2 * n)
    if char == '・':
        return 0.15 * (n - 1)
    return min(2.7, 0.7 * (n - 1))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    if not text:
        if token.count('\u00a0') >= 2:
            value = min(1.2, 0.24 * token.count('\u00a0'))
        elif set(token) == {' '} and len(token) >= 32:
            value = min(1.3, 0.00008 * len(token) ** 2)
    elif text in {'http', 'https', 'www'}:
        value = 0.9 if text == 'http' else 1.1
    elif len(text) >= 2 and len(set(text)) == 1 and text[0] != '\ufffd':
        value = repetition(text[0], len(text), token.startswith(' '))
        if '\n' in token:
            value *= 0.35 if text[0] in '?？' else 0.5
            if token.count('\n') >= 2:
                value *= 0.75
    elif text in {'?', '!', '？', '！'}:
        value = {'?': 0.79, '!': 0.59, '？': 0.56, '！': 0.46}[text]
        if '\n' in token:
            value *= 0.36 if text in '?？' else 0.54
            if text == '?' and token.count('\n') >= 2:
                value *= 0.7
    elif '\\\\' in text:
        value = 1.35
    elif '/**' in text:
        value = 0.43
    elif text.count('?') == 1:
        value = 0.78 if text.endswith('?') else 0.35
        if '\n' in token:
            value *= 0.5
    elif (text.count('!') == 1 and not any(c.isalnum() for c in text)
          and '=' not in text and '--' not in text):
        value = 0.3
    return None, float(value)

programs.haiku:
"""layers.0.mlp.down_proj:599 -- a "decorative token" detector.

The component fires on tokens that are visual decoration or emphasis rather than words:
  * runs of one repeated character: "aaaa", "XXXX", "^^^^", "********", "!!!", "====";
    long runs of letters are strongest, long symbol runs are medium, 2-character runs are weak;
  * emphatic punctuation: "?" and "!" (and their full-width forms), "||", "&&", "**", "\\\\",
    ">>>", "?!" and "!!";
  * web stems "http", "https", "www", and a few filler strings ("abc", "xyz", "###", "::").
It is near zero on ordinary words, spaces and plain punctuation such as "." and ",".

The program looks only at the newest token (its text decoded alone), so it needs no carry.
A question or exclamation mark that ends a line ("?\\n") gives a weaker response.
"""

READS = ()

# Response to a run of one repeated symbol, by the symbol (letters are handled separately).
RUN_WEIGHT = {"?": 2.4, "!": 3.0, ",": 3.0, "^": 4.0, "~": 2.5, "*": 2.5, "\\": 3.5,
              "(": 2.0, ">": 1.7, "█": 2.7, "=": 1.3, "-": 0.9, "_": 1.1, "#": 0.7,
              ".": 1.0, "+": 1.1}

# Response to a specific emphatic or decorative token.
TOKEN_WEIGHT = {"?": 0.8, "？": 0.6, "!": 0.6, "！": 0.5, "||": 0.65, "&&": 0.7, "**": 0.6,
                "\\\\": 1.4, ">>>": 0.9, "https": 1.0, "http": 0.9, "www": 1.0, "?!": 1.2,
                "!!": 1.4, "??": 1.3, "abc": 1.2, "ABC": 1.0, "xyz": 1.2, "###": 0.4,
                "::": 0.3, "✅": 0.5}


def activation(token):
    s = token.strip(" ")
    if s in TOKEN_WEIGHT:
        return TOKEN_WEIGHT[s]
    if s.rstrip("\n") in ("?", "!", "？", "！") and s != s.rstrip("\n"):
        return 0.3  # a question or exclamation mark ending a line
    if len(s) < 2 or len(set(s)) != 1 or s[0] in " \t\n\r":
        return 0.0  # not a run of one repeated character
    if s.isalpha():
        return {2: 0.4, 3: 1.5}.get(len(s), 5.5)  # repeated letters: "aa", "aaa", "aaaa"
    if len(s) == 2:
        return 0.0  # "--", "//", "))" and the like do not fire
    if len(s) == 3:
        return 0.3 * RUN_WEIGHT.get(s[0], 1.0)
    return RUN_WEIGHT.get(s[0], 1.5)


def step(carry, prefix, upstream):
    """Activation at the newest token: the token's text decides it, no context needed."""
    return carry, float(activation(prefix.token_strings[-1]))

