import unicodedata

READS = ()

# Ordered from specific endings to their more general word families.
REG_FAMILIES = (
    ('regularly', 2.3), ('regulariz', 2.5), ('regular', 3.9),
    ('regulations', 3.9), ('regulation', 3.5),
    ('regulated', 2.5), ('regulating', 2.3), ('regulat', 2.1),
    ('regul', 3.6),
    ('regardless', 2.5), ('regarded', 3.1), ('regards', 2.9),
    ('regard', 3.7),
    ('registered', 2.0), ('register', 3.5),
    ('registry', 1.9), ('registr', 2.6),
    ('regional', 1.35), ('regions', 1.9), ('region', 1.55),
    ('regexp', 2.6), ('regex', 3.2),
    ('regression', 2.3), ('regress', 1.9),
    ('regiment', 2.9), ('regimen', 2.8), ('regime', 1.7),
    ('regret', 2.2), ('regener', 1.35), ('regel', 1.6),
)

CHINESE = {
    # Registration and its beginning characters.
    '注册': 3.4, '註冊': 3.4, '登记': 1.0, '登記': 1.0,
    '注': 1.1, '登': 0.6,
    # Rules, regulations, and supervision.
    '规': 2.9, '規': 2.9, '规定': 2.2, '規定': 1.6,
    '监管': 2.6, '監管': 2.6, '法规': 2.5, '法規': 2.5,
    # Region, county, regression; and the character meaning send/mail.
    '地区': 2.1, '地區': 2.1, '郡': 3.6, '回归': 1.8,
    '寄': 3.4,
}


def spelling(raw):
    word = raw.strip().lstrip('._-/(').casefold()
    return ''.join(c for c in unicodedata.normalize('NFD', word)
                   if not unicodedata.combining(c))


def strength(raw, word):
    token = raw.strip()
    if token in CHINESE:
        return CHINESE[token]
    if word == 'рег':
        return 4.6 if raw.startswith(' ') else 2.8
    if word.startswith(('регист', 'зарегист')):
        return 1.9
    if word.startswith('регион'):
        return 1.5
    if word == 'reg':
        if 'é' in raw.casefold():
            return 3.8
        if token.startswith('-'):
            return 6.4
        if token.startswith('_'):
            return 7.0 if token.isupper() else 5.9
        if token.startswith('('):
            return 4.7
        if token.startswith(('.', '/')):
            return 5.4
        return 5.6 if raw.startswith(' ') else 6.0
    for stem, value in REG_FAMILIES:
        if word.startswith(stem):
            if word == 'register' and token.startswith(('.', '_', 'Register')):
                value = 4.5
            if word == 'regarding' and token.startswith('Regarding'):
                value = 4.7 if not raw.startswith(' ') else 4.1
            return value
    if word.startswith('reg'):
        return 1.5
    if word.startswith('irregular'):
        return 2.0
    # Weaker words expressing the same relations, restrictions, or geography.
    if word in {'concerning', 'relating', 'territorial'}:
        return 0.6
    if word == 'restricted':
        return 0.8
    if word == 'irrespective':
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = spelling(raw)
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = strength(raw, word)
    completed = word
    if previous == 'reg' and raw[:1].isalpha():
        # The reg fragment has already fired; predict only its ending here.
        if word.startswith('ulat'):
            value = 2.5
        elif word.startswith('ard'):
            value = 1.7 if word.startswith('ardless') else 2.2
        elif word.startswith(('ular', 'ist', 'imen', 'ret')):
            value = 1.5
        else:
            value = max(value, 0.5)
        completed = previous + word
    if previous == 'regular' and word.startswith('expression'):
        value = 1.9
    if word == 'to' and previous in {'regard', 'regards'}:
        value = 0.8
    if word == 'of' and previous.startswith(
            ('region', 'regulation', 'register', 'regiment', 'regime')):
        value = 0.6
    return (doc, completed), value

