# crossing/too much, and exceeding a time limit.
LIMIT_CUES = {
    '不足': -0.45,                         # insufficient
    '不可': -0.48,                         # impossible/forbidden
    '一流': -0.54,                         # first-rate
    '达到': -0.51, '達到': -0.51,           # reach
    '高达': -0.56,                         # as high as
    '跨': -0.8,                            # cross
    'すぎ': -0.8, '過ぎ': -0.6,             # Japanese: too much
    'timeout': -0.45, 'ultimate': -0.45,
