    elif word == '越':
        value = -0.73
    elif word == '초':                     # Korean: super-/first
        value = -1.15 if previous == '최' else -1.9
    elif word == 'than':
        if previous == 'more':
            value = -1.28
        elif previous == 'bigger':
            value = -0.65
        elif previous in UPWARD_COMPARISONS or previous == 'other':
            value = -0.42
        elif previous in {'higher', 'faster'}:
            value = -0.27
        elif previous in {'less', 'fewer'}:
            value = -0.22
    elif previous == 'ex' and word in {'ceed', 'ceeds', 'ceeded', 'ceeding'}:
        value = -1.5
    elif word in {'exceed', 'exceeds', 'exceeded', 'exceeding'}:
        value = -1.85
    elif word == 'exceedingly':
        value = -0.28
    elif word in {'beyond', 'oltre'}:
        value = -1.25 if word == 'beyond' else -0.9
    elif word in {'ultra', 'ultr'}:
        value = -1.65 if word == 'ultra' else -2.25
    elif word == 'ultrasound':
        value = -0.43
    elif word == 'yper' and previous == 'h':
        value = -0.95
    elif word == 'hyper':
        value = -1.35
    elif word == 'hypers':
        value = -0.58
    elif word == 'super':
