    (-8.7, ["private", "privately", "私", "私下"]),
    (-5.5, ["protected", "unprotected"]),
    (-3.8, ["priv"]),
    (-1.9, ["protect", "protects", "protecting", "protection", "protective", "保护", "保護"]),
    (-1.3, ["public", "secret", "secrets", "secretly", "confidential", "internal", "inner",
            "personal", "exclusive", "privacy", "privilege", "sacred", "hidden", "shared",
            "秘密", "内", "公共"]),
]
VALUE = {}
for value, words in LEVELS:
    for w in words:
        VALUE[w] = value

MODIFIERS = {"public", "private", "protected", "internal"}


