READS = ()

PROTECTION_WORDS = (
    "protect", "protects", "protected", "protecting", "protection",
    "protectionism", "protector",
)
PRIVACY_WORDS = (
    "privacy", "personal", "internal", "secret", "confidential",
    "privilege", "privileges",
)


def _has_word(text, word):
    text = text.lower()
    start = 0
    while True:
        at = text.find(word, start)
        if at < 0:
            return False
        before = text[at - 1] if at else " "
        end = at + len(word)
        after = text[end] if end < len(text) else " "
        if not before.isalpha() and not after.isalpha():
            return True
        start = at + 1


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "私" in token or _has_word(token, "private"):
        return None, -9.1
    if _has_word(token, "privately") or _has_word(token, "protected"):
        return None, -5.6
    if _has_word(token, "public"):
        return None, -1.4
    if _has_word(token, "static"):
        return None, -3.1
    if "密" in token:
        return None, -2.2
    if "自分" in token:
        return None, -0.6
    if any(_has_word(token, word) for word in PROTECTION_WORDS):
        return None, -2.0
    if any(_has_word(token, word) for word in PRIVACY_WORDS):
        return None, -1.1
    return None, 0.0

