JAPANESE = {
    'は': 6.1, 'には': 8.4, 'では': 6.6, 'とは': 5.1, 'のは': 4.5,
    'も': 3.6, 'にも': 6.5, 'でも': 3.9, 'のも': 3.3, 'とも': 3.0,
    'に': 1.35, 'で': 1.05, 'の': 0.77, 'を': 0.74, 'と': 1.5,
    'へ': 1.0, 'が': 0.16, 'や': 1.0, 'か': 1.0,
    'ば': 2.4, 'れば': 6.1, 'なら': 5.2, 'たら': 3.8,
    'ると': 3.5, 'だと': 3.0, 'ので': 2.2, 'なので': 2.8,
    'です': 1.4, 'だ': -0.8, 'ます': 0.8,
    'については': 6.5, '場合': 1.6,
    'たり': 2.0, 'こそ': 3.8, 'はこちら': 2.4,
    # Short verb endings, including contracted conditional -ゃ.
    'ら': 1.7, 'ゃ': 3.7, 'る': 0.85, 'た': 0.8, 'て': 0.85,
    'よ': 1.1, 'いう': 2.5, 'なんて': 3.0,
    '限り': 3.3, 'の場合': 3.0, 'でしょうか': 2.7,
}

# Topic, case and conditional markers in Korean.
KOREAN = {
    '는': 4.2, '은': 3.7, '에는': 6.8, '에서는': 4.7,
    '들은': 3.2, '도': 2.3, '에도': 3.6, '엔': 4.1,
    '면': 4.0, '다면': 4.8, '으면': 4.1, '하면': 3.2,
    '의': 0.9, '에': 0.85, '에게': 1.0, '에서': 0.6,
    '을': 0.25, '를': 0.3, '와': 0.7, '과': 0.55,
    '이': -1.1, '그': -1.3, '지만': 1.8, '만': 1.1,
    '므로': 2.3, '고': 0.6, '로': 0.45, '으로': 0.65,
    '경우': 4.2, '따라': 3.0, '대한': 1.4, '니까': 2.0,
}


def activation(text):
    s = text.strip()
    word = s.lower()
    if word == 'was':
        return 0.8
    if word == 'were':
        return 0.88
    if word in {'wasn', 'weren'}:
        return 0.35
    if word == 'been':
        return 0.13
    # Additional/conditional focus markers in several languages.
    if word in {'auch', 'aussi', 'также', 'же', 'cũng'}:
        return 0.8
    if s == 'thì':
        return 2.7
    if s in {'那', '那么', '则', '則'}:
        return 0.9
    if s == 'จะ':
        return 1.9
    if s in JAPANESE:
        return JAPANESE[s]
