    if s in {'これ', 'それ', 'あれ', 'どこ', 'どう', 'あなた', 'そ'}:
        return -1.5
    if s in {'なん', 'そう', 'こう', 'こ'}:
        return -0.7
    if s in {'これが', 'それが', 'あれが', 'これを', 'それを', 'あれを'}:
        return -1.3
    if s in {'ここ', 'そこ', 'あそこ'}:
        return -2.3
