# component's own activation).
CASE_PARTICLES = ("の", "を", "に", "で", "と", "や", "へ", "から", "まで", "です", "として")
ALSO = ("も", "でも", "にも")
KOREAN_TOPIC = ("은", "는", "도", "에서는", "에도")
CONDITIONALS = ("れば", "なら", "たら", "ても", "ば", "ては", "ければ", "えば", "으면", "면", "하면", "되면")
DEMONSTRATIVES = ("この", "その", "이")


def is_hiragana(text):
    return len(text) > 0 and all("぀" <= c <= "ゟ" for c in text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token.endswith("は"):
        value = 6.0  # topic marker は, and compounds such as では, には, とは
    elif token in ALSO:
        value = 4.0
    elif token in KOREAN_TOPIC:
        value = 3.5
    elif token.endswith(CONDITIONALS):
        value = 4.5
    elif token in CASE_PARTICLES:
        value = 1.2
    elif is_hiragana(token):
        value = 0.3
    elif token in ("was", "were"):
        value = 0.9
    elif token in DEMONSTRATIVES:
        value = -2.0
    else:
        value = 0.0
    return carry, float(value)

