"""layers.0.mlp.down_proj:604 - the indefinite article "a" / "an".

This component fires on the English indefinite article (a, an, and capitalised or
glued forms) and on the "some / another" determiners. How strongly depends on the
word just before it:

- after a conjunction, complementiser or wh-word ("and a", "that a", "not a",
  "such a", "what a", "if a", "than a"): strongest, about 3;
- after a preposition or copula ("of a", "is a", "with a", "in a", "as a", "be a")
  or after punctuation (", a", ". A"): about 1.8;
- after most other words (verbs, nouns, adverbs): about 1.4 with a space before the
  word, about 0.7 when the word is glued to the article (word fragments, identifiers);
- after "have / has / had / make / give / add / form ..." it is weak, about 0.6;
- after a creation or provision verb ("create a", "provides a", "offers a") it turns
  slightly negative, about -0.5;
- after a symbol, bracket or digit (code and maths, "= a", "(a", "2 a"): about 0.8;
- "some", "another", "any": about 0.7.

Everything that is not one of these words predicts 0.

Stateless: each position is read from the current token and the one before it.
"""
READS = ()

ARTICLES = {"a", "an", "A", "An", "AN"}
SOME = {"some", "Some", "another", "Another", "any", "someone", "something"}
CREATE = {"create", "creates", "created", "creating", "provide", "provides", "provided", "providing",
          "offer", "offers", "offered", "offering", "present", "presents", "issue", "issued"}
HAVE = {"have", "has", "had", "having", "make", "made", "makes", "give", "gives", "gave", "giving",
        "add", "adds", "form", "forms", "develop", "produce", "produces", "contain", "contains"}
CONJ = {"and", "or", "if", "when", "that", "not", "such", "what", "how", "whether", "than", "without",
        "like", "only", "but", "which", "while", "even", "once", "just", "since", "where", "When", "If",
        "Such", "What", "But", "How", "Only", "Like", "And", "That", "Not", "Without", "This"}
PREP = {"of", "is", "was", "be", "been", "being", "were", "as", "for", "with", "by", "in", "on", "to",
        "from", "at", "into", "after", "before", "between", "within", "through", "during", "As", "For", "In", "With", "After"}
PROSE_PUNCT = {",", ".", ";", ":", "\n", "!", "?"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in SOME:
        return None, 0.7
    if word not in ARTICLES:
        return None, 0.0
    if prefix.position == 0:
        return None, 1.05
    raw = prefix.token_strings[-2]
    prev = raw.strip()
    if prev in CREATE:
        return None, -0.5
    if prev in HAVE:
        return None, 0.6
    if prev in CONJ:
        return None, 3.0
    if prev in PREP or prev in PROSE_PUNCT:
        return None, 1.8
    if not prev or not prev[0].isalpha():
        return None, 0.8
    if not raw.startswith(" "):
        return None, 0.7
    return None, 1.4

