    elif lower == 'forest':
        value = 3.75 if word.istitle() else 4.0
    elif lower == 'forecast':
        value = 3.85 if boundary else (4.35 if word.istitle() else 3.3)
    elif lower == 'otherwise':
        value = 4.75 if word.islower() else (4.4 if boundary else 3.8)
        if word.islower() and prev.lower() in {
            'would', 'could', 'because', 'since', 'unless'
        }:
