"""Partial spelling-based approximation of an early word-fragment feature.

Apply the same lowercase spelling rules to Latin and romanized Cyrillic:
-em is negative, especially in short pieces. Four-letter vowel/consonant/e
pieces ending in l, m, n, or t receive an additional negative contribution.
Related -ern, -ent, and -est shapes are also negative. Initial e adds a
small positive offset. Everything else stays near zero.

These rules describe a tendency, not a semantic category, and leave most
of the component's activation variance unexplained. No context is used.
"""
import re

READS = ()
ROMAN = str.maketrans({
    'а': 'a', 'б': 'b', 'в': 'v', 'г': 'g', 'д': 'd', 'е': 'e',
    'ж': 'zh', 'з': 'z', 'и': 'i', 'й': 'y', 'к': 'k', 'л': 'l',
    'м': 'm', 'н': 'n', 'о': 'o', 'п': 'p', 'р': 'r', 'с': 's',
    'т': 't', 'у': 'u', 'ф': 'f', 'х': 'kh', 'ц': 'ts', 'ч': 'ch',
    'ш': 'sh', 'щ': 'shch', 'ъ': '', 'ы': 'y', 'ь': '',
    'э': 'e', 'ю': 'yu', 'я': 'ya',
})
CONSONANTS = 'bcdfghjklmnpqrstvwxyz'
CLOSED_E = re.compile('[aiou][' + CONSONANTS + ']e[lmnt]')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].translate(ROMAN)
    value = 0.002
    if not (token.isascii() and token.isalpha() and token.islower()):
        return None, value
    if token.startswith('e'):
        value += 0.006
        if len(token) > 4:
            value += 0.018
        if len(token) >= 3 and token[1] in CONSONANTS:
            if token[2] in 'aiouy':
                value += 0.018
    if token.endswith('em'):
        value -= 0.024
        if len(token) in (3, 4):
            value -= 0.115
        if len(token) >= 3:
            onset = token[-3]
            if onset in 'lr':
                value -= 0.095
            elif onset in 'tsfhz':
                value -= 0.078
            elif onset in 'mn':
                value -= 0.05
            elif onset in 'bdg':
                value -= 0.03
    if token.endswith('el'):
        value -= 0.05
    if CLOSED_E.fullmatch(token):
        value -= {'m': 0.095, 'l': 0.06, 'n': 0.044, 't': 0.27}[token[-1]]
        if token[-1] == 'm' and token[0] == 'a':
            value -= 0.375
        if token[-1] == 'n' and token[1] in 'lnr':
            value -= 0.08
    if re.fullmatch('[aiou][' + CONSONANTS + ']ern', token):
        value -= 0.15
    if re.fullmatch('[aiou][' + CONSONANTS + ']ent', token):
        value -= 0.067
    if re.fullmatch('[aiou]est', token):
        value -= 0.25
    return None, value

