        if '\n' in token:
            value = 0.0
        elif text == '>>>':
            value = -0.7
        else:
            value = -0.8 if start else -0.16 if not bare else 0.0
    elif word in {'open', 'require'}:
        value = 0.18 if not bare else 0.4
        if start:
            value += 0.3
    elif text == 'INTO':
        value = 0.85
    elif word == 'crate':
        value = 2.0 if last_word == 'extern' else 0.45
    elif text in {'<tool_call>', '</tool_call>', '<think>'}:
        value = 0.16
    elif text == '<tool_response>':
        value = -0.13
    elif text == '@':
        value = -0.23 if not bare else 0.0

    if text == '@@' and start and bare:
        hunk = True
    if text in {'</tool_response>', '</diff>'}:
        hunk = False

    # Keep the unfinished line and the most recently completed line.
    combined = line + token.replace('\\n', '\n').replace('\\r', '\r')
    parts = combined.split('\n')
    if len(parts) > 1:
        previous_line = parts[-2][-180:]
    line = parts[-1][-180:]
    return (doc, line, previous_line, token, position + 1, hunk), float(value)

