"""layers.0.mlp.down_proj:610, a rank-one piece of layer 0's MLP output.

What it does: it fires on words that name type, module or declaration constructs in
source code ("type", "namespace", "using", "module", "class", "package", "interface",
"fn", "function", "table", ...), positive, strongest on "using", "namespace", "type".
It is negative on diff or patch markers at the start of a line: a "+" that begins an
added line (strongest), "@@" hunk headers, and ">" quote or diff lines. Everything else
is predicted as 0.

Why: the component's activation is mostly a sparse set of token identities. A short
concept list captures the big keyword and diff-marker cases; the long tail of rare tokens
is not captured, so the variance explained is modest (about 0.24 on eval).
"""

READS = ()

TYPE_WORDS = {"type", "typeof", "rtype", "ype"}
STRONG = {"namespace": 1.2, "crate": 0.9}
MEDIUM = {"module", "class", "package", "interface", "trait", "struct", "contract",
          "attribute", "library", "theorem", "derive", "types"}
WEAK = {"fn", "func", "function", "table", "enum", "impl", "require", "open"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    cur = raw.strip()
    word = cur.lower().lstrip("-_.")
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
    line_start = "\n" in prev or len(prefix.token_strings) == 1
    bare = raw[:1] != " "  # no leading space: start of a line, after a tab or a symbol
    if word in TYPE_WORDS:
        return None, 0.9
    if word == "using":
        return None, 1.4 if bare else 0.2
    if word == "from":
        return None, 0.8 if bare else 0.0
    if word == "import":
        return None, 0.6 if raw[:1] == "\t" else 0.0
    if cur == "#include":
        return None, 0.4
    if word in STRONG:
        return None, STRONG[word]
    if word in MEDIUM:
        return None, 0.5
    if word in WEAK:
        return None, 0.25
    if cur == "+" and line_start:
        return None, -1.5
    if cur in ("+\n", "@@"):
        return None, -1.1
    if cur == ">" and line_start:
        return None, -0.6
    if cur == "+" or cur == ">":
        return None, -0.1
    if cur == "@":
        return None, -0.25
    return None, 0.0

