"""A lexical sketch of a sparse code-and-document-markup feature.

The harvest showed positive examples around type/declaration words and other
technical vocabulary, with negative examples on line-leading diff/quote marks.
This deliberately predicts only those readable word classes and markers.
"""

READS = ()

TYPE_TERMS = {
    "enum", "class", "void", "jclass", "instanceof", "typing",
    "contract", "qual", "eventhandler", "rtype", "edge",
}
CODE_TERMS = {
    "function", "func", "from", "into", "key", "set", "open",
    "test", "library", "table", "attributes", "async",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = prefix.token_strings[-2] if same_document else ""
    word = token.strip().strip(".,;:()[]{}<>\"'`_- ").lower()

    if "type" in word or word in TYPE_TERMS:
