"""Negative responses to delta notation and several marked letters/symbols.

The largest letter response is to a standalone stroked D (đ/Đ); it weakens
when the token contains a whole Vietnamese syllable. Exposed ñ and a with
circumflex/diaeresis, Cyrillic D, section and registered signs also respond.
Greek prose strengthens delta, less so with polytonic (ancient) spelling.
For split UTF-8 characters, completed mathematical glyphs are recognized too.
The rules cover strong recurring written forms, not weak lexical details.
"""
READS = ()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != document
    if new_document:
        recent = ()
    else:
        recent = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    space = token.startswith(' ')
    split_character = False
    if not new_document and '\ufffd' in token:
        # A byte fragment may have just completed a readable Unicode character.
        last_character = prefix.text_prefixes[-1][-1:]
        if last_character and last_character != '\ufffd':
            word = last_character
            split_character = True
            space = False
    greek_context = sum(kind > 0 for kind in recent) >= 2
    polytonic_context = 2 in recent
    value = -0.002

    if word in ('Δ', 'δ', '∆'):
        if polytonic_context:
            value = -1.97 if word == 'δ' else -2.5
        elif greek_context:
            value = -2.72 if word == 'δ' else -3.05
        elif word == 'δ':
            value = -1.4 if space else -1.55
        else:
            if word == 'Δ':
                value = -2.0
            else:
                value = -2.57 if split_character else -1.65
    elif word.strip('(_\\') in ('delta', 'Delta'):
        if word == 'Delta':
            value = -0.8 if space else -1.42
        else:
            value = -1.12
    elif word.startswith(('đ', 'Đ')):
        if len(word) == 1:
            value = -5.5
        elif word.lower() == 'đi':
            value = -3.05
        else:
            value = -1.35 / (len(word) - 1)
    elif word.startswith(('ñ', 'Ñ')):
        value = -2.62 * 0.56 ** (len(word) - 1)
    elif word.endswith(('ñ', 'Ñ')):
        value = -0.7 if len(word) <= 3 else -0.08
    elif word == 'Д':
        value = -0.70 if space else -0.38
    elif word == 'д':
        value = -0.20
    elif word in ('§', '§§', '.§'):
        value = (-2.26 if space else -1.75) / word.count('§')
    elif word in ('®', '®,'):
        value = -3.0 if space else -1.95 / len(word)
    elif word in ('â', 'Â'):
        value = (-1.35 if word == 'â' else -0.9) if space else -0.35
    elif word in ('ä', 'Ä'):
        value = -0.9 if word == 'Ä' else (-0.30 if space else -0.2)
    elif word == 'Γ':
        value = -0.65
    elif word == 'ð':
        value = -1.85
    elif split_character and word in ('√', '∂', '∑', '∐', '∠'):
        value = -0.8 if word in ('∑', '∐', '∠') else -0.5

    # A short rolling indication of Greek prose, reset at document boundaries.
    if any('\u1f00' <= c <= '\u1fff' for c in token):
        script = 2  # Greek extended characters carry polytonic accent marks.
    elif any('\u0370' <= c <= '\u03ff' for c in token if c not in 'ΔδΓ'):
        script = 1
    else:
        script = 0
    return (document, (recent + (script,))[-8:]), float(value)

