    'kind': (1.1, -2.6), 'type': (2.1, -3.4), 'sort': (0.75, -3.9),
    'kinds': (1.15, -1.7), 'types': (2.7, -2.75), 'sorts': (1.0, -2.25),
}
ATTRIBUTE_OF = {
    'form': -1.32, 'level': -1.35, 'size': -1.20, 'degree': -1.25,
    'species': -1.17, 'quality': -0.99, 'style': -1.46, 'shape': -1.19,
    'amount': -0.82, 'bit': -0.84, 'piece': -0.72, 'nature': -0.82,
    'magnitude': -0.88, 'extent': -0.71, 'name': -0.71, 'length': -0.56,
    'version': -0.60, 'class': -0.61, 'thickness': -0.60,
    'quantity': -0.56, 'strength': -0.57, 'measure': -0.56,
    'manner': -0.63, 'mode': -0.68, 'choice': -0.55,
    'state': -0.44, 'method': -0.41, 'design': -0.50,
    'source': -0.49, 'volume': -0.35, 'variety': -0.34,
    'part': -0.29, 'way': -0.31, 'number': -0.16,
    'category': -0.64, 'classification': -0.63, 'genus': -0.56,
    'format': -0.79, 'grade': -0.85, 'standard': -0.58, 'scale': -0.62,
}
