RELATED = frozenset({
    '类', '類', '種', '这种', '这样的', '一種',  # Kind/type, such a kind.
    'ような', 'そんな', '感じ', '样子', '樣',  # Like, such, appearance.
    '程度', 'くらい', 'ぐらい', 'ほどの', '大小',  # Degree, about, size.
    'とか', 'だけ', 'もの', 'ったり', 'したり',  # Alternatives, only, thing.
})


