        base, sensitivity = CATEGORY[word]
        value = base - sensitivity * DETERMINER.get(previous, 0.0)
        if not token.startswith(' '):  # Identifier or unspaced spelling.
            value = {'kind': -1.4, 'type': -0.05, 'sort': -0.8}[word]
        if token.strip() in {'Type', 'TYPE'}:
