                      'different': 0.28, 'all': 0.17}.get(previous, 0.0)
        elif word == 'types' and previous in {'the', 'these', 'different'}:
            value = -0.15
    elif word == 'of':
        if previous in CATEGORY_OF:
            multiplier, offset = CATEGORY_OF[previous]
            value = multiplier * previous_value + offset
        else:
            singular = previous
            if previous not in ATTRIBUTE_OF and previous.endswith('s'):
                singular = previous[:-1]
            value = ATTRIBUTE_OF.get(singular, 0.0)
            if previous != singular:
                value *= 0.78
        if token in {'_of', 'Of'}:
            value *= 0.67
