"""Indication words and ind- spelling, with a one-token grammatical echo.

The strongest responses are 'indicat-' and the fragment 'ind'. Other ind-
families, signals, flags, suggestions and several Chinese equivalents respond
less. This is lexical, not a general test of whether a sentence implies anything.
Unmatched tokens are zero; weaker token-specific background responses are omitted.
"""
READS = ()

SIGNALLING = {
    'suggest', 'suggests', 'suggested', 'suggesting',
    'imply', 'implies', 'implied', 'implying',
    'sign', 'signs', 'flag', 'flags', 'flagged',
    'identifier', 'identifiers', 'pointer', 'ptr', 'idx',
}


def lexical(s):
    w = s.lstrip(' \t\r\n_-.([/').lower()
    if w == 'ind':
        if s.lstrip() == 'IND':
            return 2.1 if s[:1].isspace() else 0.85
        return 3.2 if s != 'ind' else 1.6
    if w.startswith('indicat'):
        verbs = ('indicate', 'indicates', 'indicated', 'indicating')
        return 3.85 if w in verbs else 3.2
    if w in ('indic', 'indica'):
        return 3.1
    if w.startswith('indiqu'):
        return 1.9
    if w.startswith('individ'):
        return 1.0 if w.endswith('s') else 1.5
    if w.startswith('indice'):
        return 1.4
    if w.startswith(('index', 'independ')):
        return 0.2
    if w == 'india':
        return 0.35
    if w.startswith('indeed'):
        return 0.0
    if w.startswith(('indirect', 'indent', 'induct', 'indiffer', 'indemn')):
        return 1.25
    if w.startswith('indigen'):
        return 2.4 if s.lstrip()[:1].isupper() else 1.25
    if w.startswith('ind'):
        return 0.8
    if w == 'signal':
        return 0.62
    if w in SIGNALLING or w.startswith('signal'):
        return 0.8
    if w.startswith('suggestion'):
        return 0.32
    if w in ('specify', 'specified', 'specifies', 'specifying'):
        return 0.5
    if w in ('signify', 'signifies', 'signified'):
        return 1.15
    if s in ('产业', '產業', '指示'):
        return 2.5                 # industry; indication
    if s in ('指标', '个体'):
        return 1.7                 # indicator; individual
    if s in ('指', '示', '表示', '表明', '指出', '标志', '旗', '间接'):
        return 1.05                # pointing, showing, signs; indirect
    if s in ('个人', '行业', '标', '標', '指定', '提示', '说明', '感'):
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    before = previous.lstrip(' \t\r\n_-.([/').lower()
    w, value = s.strip().lower(), lexical(s)
    if s.startswith('ind') and previous[-1:].isalpha():
        value = 0.15
    if s == 'ind':
        value = 1.5 if previous[-1:].isalpha() else 2.6
    if before in ('ind', 'indic', 'indica') and s.isalpha():
        joined = before + w
        value = 0.7
        if joined.startswith(('indicat', 'indiqu')):
            value = 2.7
        elif joined.startswith(('indent', 'induct', 'induc', 'indem', 'indigen')):
            value = 1.25
    if w == 'of' and before in ('indication', 'indications', 'indicator',
                                'indicators', 'indicative', 'induction'):
        value = 1.5
    if before in ('indicate', 'indicates', 'indicated', 'indicating'):
        if w in ('the', 'a', 'an', 'to', 'by'):
            value = 0.56
        elif w == 'that':
            value = 0.14
    return (doc, s), float(value)

