READS = ()
EXTENT = set('far soon early high low small little simple quickly easy'.split())
DEGREE = set('long much many large big fast young short few strong'.split())


def as_response(words):
    if not words:
        return -0.2
    last = words[-1]
    # Fixed linking phrases, including compounds such as 'insofar as'.
    if last == 'such':
        return -2.75
    if last == 'same':
        return -3.45
    if last == 'so':
        return -3.6
    if last == 'well':
        return -4.85
    if last in {'far', 'soon', 'early'}:
        return -8.1
    if last.endswith('sofar'):
        return -7.0
    if last.endswith('asmuch'):
        return -5.5
    # Expanded quantitative comparisons: 'as far back as', 'as many days as'.
    if len(words) >= 3 and words[-3] == 'as':
        if words[-2] == 'far':
            return -7.5
        if words[-2] in {'many', 'much'}:
            return -4.5
    # Coordinated adjectives: 'as legal and valid as'.
    if len(words) >= 4 and words[-4] == 'as' and words[-2] in {'and', 'or'}:
        return -3.5
    # Find a nearby opening of an equality or example construction.
    for gap, word in enumerate(reversed(words[-5:])):
        if word == 'so' and gap:
            return -4.5 if gap == 1 and last in EXTENT | DEGREE else -0.4
        if word == 'as' and gap:
            if gap == 1:
                if last in EXTENT:
                    return -7.8
                if last in DEGREE:
                    return -6.1
                return -4.6
            return -0.4 - 5.0 * 0.55 ** (gap - 1)
        if word in {'same', 'such'}:
            return -0.4 - 3.0 * 0.72 ** gap
    if last in EXTENT | DEGREE | {'good', 'hard', 'important', 'close'}:
        return -2.5
    return -0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    word = token.strip()
    if word.lower() in {'as', 'than'}:
        clause = re.split(r'[.,;:!?\n]', text.lower())[-1]
        words = re.findall(r'[a-z]+|[^\w\s]', clause)[-10:]
        last = words[-1] if words else ''
        if word.lower() == 'than':
            value = -1.5
            if last == 'rather':
                value = -0.32
            elif last == 'other':
                value = -0.85
            elif last in {'higher', 'lower', 'smaller', 'slower', 'easier'}:
                value = -2.3
        elif word != 'as':
            value = -0.95 if not text else -0.06
        elif not text:
            value = -2.5 if token[:1].isspace() else -1.07
        elif token[:1].isspace() or not text[-1:].isalpha():
            value = as_response(words)
        else:
            value = -0.2
    return (doc, (text + token)[-160:]), float(value)

