"""Component layers.0.mlp.down_proj:615 (Qwen3-1.7B, layer 0 MLP down projection).

What it does: it reads the "as ... as" comparison construction. It goes strongly
negative on the second "as" of a correlative comparison ("as far as", "as soon as",
"as early as", "as long as", "as much as", "as well as"), moderately negative on
"such as" and "same ... as", mildly negative on the comparative "than", and is
near zero everywhere else.

Main program: `step` looks at the newest token only, plus the previous token, and
answers with a fixed value per case. Values are the mean activations seen on
training rows, rounded.
"""

READS = ()

# Second "as" after an adverb of extent, e.g. "as far as", "as soon as".
COMPARATIVE_ADVERB_AS = {"far": -8.5, "soon": -8.4, "early": -7.8,
                         "long": -6.4, "much": -6.5, "well": -4.8}
# "such as" and "same ... as" (introducing an example or a standard).
SUCH_SAME_AS = {"such": -2.8, "same": -3.4}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " than":
        return None, -1.4
    if token != " as":
        return None, 0.0
    t = len(prefix.token_strings) - 1
    prev = ""
    if t >= 1 and prefix.document_ids[t - 1] == prefix.document_ids[t]:
        prev = prefix.token_strings[t - 1].strip()
    if prev in COMPARATIVE_ADVERB_AS:
        return None, COMPARATIVE_ADVERB_AS[prev]
    # Other "as" right after an earlier "as" in the same comparison, e.g. "as simple as".
    for k in range(1, 4):
        if t - k < 0 or prefix.document_ids[t - k] != prefix.document_ids[t]:
            break
        if prefix.token_strings[t - k].strip() in ("as", "As"):
            return None, -6.0
    return None, SUCH_SAME_AS.get(prev, -0.2)

