"""Estimate the negative response to English comparison markers and their frames."""
import re

READS = ()
_CORRELATIVE_END = re.compile(r"\bas(?:\s+\w+){1,3}\s*$")
_SUCH_AS = re.compile(r"\bsuch\s*$")
_SAME_AS = re.compile(r"\bsame\s*$")

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        past = ""
    else:
        past = carry[1]

    token = prefix.token_strings[-1].casefold()
    history = past.casefold()
    value = 0.0
    if token == " as":
        if _CORRELATIVE_END.search(history):
            value = -4.9
        elif _SUCH_AS.search(history):
            value = -2.7
        elif _SAME_AS.search(history):
            value = -3.5
        else:
            value = -0.54
    elif token == " than":
        value = -1.5

    recent = (past + prefix.token_strings[-1])[-100:]
    return (doc, recent), float(value)

