        if newline:
            value -= 0.2
        elif space:
            value += 1.5
    elif s and set(s) <= {' ', '\xa0'} and '\xa0' in s:
        n = s.count('\xa0')
        if prev.endswith('\xa0') or start:
            value = 2.6 if ' ' in s else 3.25 + (0.5 if n in (3, 7) else 0.0)
        elif space:
            value = 1.1
        else:
            value = 0.8 if n in (3, 7) else 0.0
    elif s == '\\t':
        value = 0.62 if prev == 'n' else 1.17
    elif s and set(s) == {' '}:
        n = len(s)
        if start and n >= 2:
            value = 0.44 if n == 3 else (0.85 if n == 2 else 1.2)
        elif n >= 64:
            value = 0.9 if space else 0.4
        elif n == 1:
            value = -0.08 if newline or start else -0.007
        else:
            if prev == 'n':
                value = 0.37 if n <= 3 else max(0.2, 0.78 - 0.009*n)
            elif newline:
                value = 0.2 if n in (5, 6) else (0.12 if n % 4 == 1 else 0.0)
            elif prev.endswith('\t'):
                value = 0.8
            else:
                value = 0.35 if n % 2 else 0.15
    elif s.lstrip().startswith(('}', ')', ']')):
        if prev and prev.isspace() and not newline:
            value = -0.65 if space else -0.78
            if ',' in s:
                value -= 0.2
            if s.count('\n') >= 2:
                value += 0.15
    elif s == '``':
        value = 1.9 if prev.endswith('\xa0') else (0.12 if newline else 0.3)
    return (doc, s), float(value)

