"""A weak text-layout cue: tab-only whitespace is positive; some closing delimiters negative.

The estimates are shrunk because these token shapes do not determine when the
component fires; most other tokens are predicted inactive.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token and not token.strip():
        value = 1.8 * token.count("\t")
    else:
        stripped = token.lstrip()
