"""Negative responses to the spelling 'time(s)' and multiplication notation.

'Times' and × are strongest, whether used in arithmetic, occasions, or
newspaper titles. Singular time, multiplication words, and literal \\t are
weaker. A few phrase rules handle same time, at times, and multiplied by.
Cross marks and translations of time/repetition have smaller responses.
Other tokens receive zero. State remembers only five preceding tokens and
resets between documents.
"""
READS = ()

MULTIPLY = {'multiply', 'multiplied', 'multiplying', 'multiplication'}
DIVIDE = {'divide', 'divided', 'dividing', 'divisible'}
ARITHMETIC_WORDS = MULTIPLY | DIVIDE
NUMBERS = set('one two three four five six seven eight nine ten several'.split())
# Small responses to multiplication/repetition words and related symbols.
SMALL_RESPONSES = {
    'twice': -1.08, 'fois': -1.2, 'veces': -1.7, 'vezes': -1.7,
    '倍': -1.05, '乘': -2.1, 'cdot': -1.2, '÷': -1.4, '⊗': -1.35,
    '·': -0.37, '⋅': -0.37, '✖': -2.4, '✗': -0.7,
    '时间': -0.7, '時間': -0.7, 'время': -0.32, 'времени': -0.32,
    'zeit': -0.32,
}
# Responses when a byte token completes one of these symbols.
COMPLETED_SYMBOLS = {
    '÷': -1.8, '⊗': -2.65, '✗': -1.55, '✖': -1.25, '×': -4.3,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = () if carry is None or carry[0] != doc else carry[1]
    previous = recent[-1] if recent else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    before = previous.strip().lower()
    number_before = previous.rstrip()[-1:].isdigit()
    value = SMALL_RESPONSES.get(lower, 0.0)
    # Some symbols are split across UTF-8 byte tokens. Use the completed
    # character only at the token that completes it.
    if '\ufffd' in token and recent:
        completed = prefix.text_prefixes[-1][-1:]
        value = COMPLETED_SYMBOLS.get(completed, 0.0)

    if word == '×':
        value = -4.5 if token.startswith(' ') else -4.2
        if previous == '\xa0':
            value = -5.0
    elif lower == 'times':
        value = -4.2 if token.startswith(' ') else -5.2
        if word != 'times':
            value = -4.85
        elif previous.endswith('\\'):
            value = -5.25
        elif before in {'at', 'all', 'which', 'relevant'}:
            value = -2.4
        elif before in {'many', 'more', 'multiple'}:
            value = -3.1
        elif number_before:
            value = -4.4
        elif before in NUMBERS:
            value = -3.75
    elif lower in {'_times', '(times', '.times', '-times'}:
        value = -2.8 if word[0] in '_(' else -4.7
    elif word == 'imes':
        value = -5.8 if previous.endswith('\\t') else -1.75
    elif word == '\\t':
        value = -0.82
    elif lower == 'time':
        value = -0.88 if word == 'time' else -0.92
        if before == 'same':
            value = -0.27
        elif before in {'long', 'short', 'real', 'some', 'any', 'this', 'that'}:
            value = -0.6
        elif before in {'at', 'over'}:
            value = -0.45
    elif lower.lstrip('_.-("*') == 'time':
        value = -0.65
    elif lower in MULTIPLY:
        value = -0.68
    elif lower == 'by':
        if before in MULTIPLY:
            value = -1.85
        elif before in DIVIDE or any(w.strip().lower() in ARITHMETIC_WORDS
                                     for w in recent):
            value = -1.1
    elif word in {'*', 'x', 'X'}:
        if word == '*':
            value = -0.65 if number_before else -0.32
            if '\n' in previous:
                value = -0.08
        elif number_before:
            value = -0.5 if token.startswith(' ') else -0.38
    elif lower in {'the', 'of'} and before == 'times':
        value = -0.5 if lower == 'the' else -1.4

    return (doc, (recent + (token,))[-5:]), float(value)

