"""Approximate a sparse time-and-multiplication feature.

It is strongest on “times” and the × sign, and weaker on “time” and
ordinary multiplication notation.  For x and *, require a preceding
number or expression-like token to avoid treating every letter or bullet
as an operator.  This is a lexical approximation, not a full parser.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
    numeric = any(ch.isdigit() for ch in prev) and not any(ch.isalpha() for ch in prev)
    expression_end = bool(prev) and (prev[-1].isalnum() or prev[-1] in ")]}")

    if token == "×":
        value = -4.4
    elif token in {"imes", "times"}:
        value = -5.6 if token == "imes" else -3.9
    elif token in {"time", "-time", "twice"}:
        value = -0.95
    elif token == "время":
        value = -0.5
    elif token == r"\t":
        value = -0.95
    elif token == "∧":
        value = -0.33
    elif token == "by" and "divid" in prev.lower():
        value = -1.0
    elif token == "x" and numeric:
        value = -0.65
    elif token == "*" and expression_end:
        value = -0.65
    else:
        value = 0.0
    return None, value

