"""A conservative detector for names and stock text in example programs.

Emit negative activations for personal-name fields, greetings, foo, and
sample Person/Student/Employee identifiers, age fields, and my-prefix
identifiers. Small offsets model tool/reasoning markup. JSON name keys have
a separate estimate. Ordinary spaced prose uses smaller values. Other
words are left near zero. All-caps words are ignored; document-initial
negative responses are stronger. This does not explain the weak background.
"""
import re

READS = ()
PERSONAL_NAMES = set(
    'firstname lastname fullname surname apellido fname lname'.split()
)
EXAMPLE_CLASSES = set('employee student person animal dog'.split())
MARKUP = {'<tool_call>': 0.106, '</think>': -0.116,
          '<think>': 0.038, '</tool_call>': 0.028}
CODE = re.compile(r'[=_{};]|\b(?:class|def|function|var|let|new|this|self)\b')
LAST_WORD = re.compile(r'[A-Za-z]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text, position = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    core = token.lstrip(' \t\n\r._(/:$@')
    if core == token and token[:1].isalpha():
        piece = LAST_WORD.search(text)
        if piece and token.islower():
            core = piece[0] + token if len(piece[0]) <= 3 else ''
    word = core.lower()
    code = bool(CODE.search(text[-120:]))
    identifier = not token[:1].isspace() or (code and core[:1].isupper())
    value = -0.002
    if word == 'name':
        if core == 'Name':
            value = -0.04
        elif text.rstrip().endswith('{"'):
            value = -0.49
        elif token.startswith('.'):
            value = -0.22
        elif token.startswith('_'):
            value = -0.1
        else:
            value = -0.35 if identifier else -0.18 if code else 0.03
    elif word in PERSONAL_NAMES:
        camel = core[:1].islower() and any(c.isupper() for c in core[1:])
        value = -1.3 if camel else -0.7 if identifier or code else -0.3
    elif word in {'hello', 'greet', 'greeting', 'greetings'}:
        quoted = text.rstrip().endswith(('"', "'"))
        if not identifier:
            value = -0.3
        elif core.islower():
            value = -0.95
        else:
            value = -0.85 if quoted else -0.36
    elif word == 'foo':
        value = -0.85 if identifier else -0.65
    elif word in EXAMPLE_CLASSES:
        value = -0.65 if identifier else -0.18 if core[:1].isupper() else -0.03
    if word == 'age':
        value = -0.6 if identifier else -0.1
    elif word == 'my':
        value = -0.2 if identifier else 0.01
    if token in MARKUP:
        value = MARKUP[token]
    if core.isupper():
        value = -0.002
    if position == 0 and value < -0.05:
        value = max(-1.3, value * 1.6)
    return (doc, (text + token)[-160:], position + 1), float(value)

