NEED = {
    'need': -3.66,
    'needs': -3.30,
    'needing': -3.30,
    'needed': -2.04,
}
HAVE = {
    'have': -2.12,
    'has': -1.93,
    'had': -1.64,
    'having': -1.83,
}
DESIRE = {
    'want': -1.30,
    'wants': -1.22,
    'wanted': -0.96,
    'wanting': -1.51,
    'wish': -1.03,
    'wishes': -1.03,
    'desire': -1.30,
}
REQUIRE = {'require', 'requires', 'required'}
ABILITY = {'ability', 'inability', 'capability', 'important', 'essential',
           'expected', 'forced', 'permission', 'responsibility'}
SOFTENERS = {'not', "'t", '’t', 'never', 'would'}
PRONOUNS = {'you', 'it', 'us', 'them', 'me', 'him', 'her'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = before = ''
    if carry is not None and carry[0] == doc:
        _, previous, before = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word == 'to':
        if previous in NEED:
            value = NEED[previous]
            if previous == 'need':
                if before in {'the', 'a', 'no'}:
                    value -= 0.5
                elif before in SOFTENERS:
                    value += 0.35
        elif previous in HAVE:
            value = HAVE[previous] + (0.18 if before in SOFTENERS else 0.0)
        elif previous in DESIRE:
            value = DESIRE[previous] + (0.15 if before in SOFTENERS else 0.0)
        elif previous == 'necessary':
            value = -1.5
        elif previous in REQUIRE or previous == 'ought':
            value = -1.25
        elif previous in ABILITY:
            value = -0.7
        elif previous in PRONOUNS:
            if before in NEED:
                value = -1.3
            elif before in DESIRE or before in REQUIRE:
                value = -0.65
    elif word == 'not' and previous == 'need':
        value = -1.8
    elif word == 'for' and previous in NEED:
        value = -2.27 if previous == 'need' else -0.9
    elif word == 'need' and previous in {'the', 'no', 'a'}:
        value = -0.77 if previous == 'a' else -1.1
    elif token.startswith(' ') and word in DESIRE:
        value = 0.2
    elif word in REQUIRE:
        value = 0.25
    elif word == 'that' and previous in REQUIRE:
        value = -0.35
    return (doc, word, previous), value

