READS: tuple[str, ...] = ()

NEED_TO = {"need", "needs"}
HAVE_TO = {"have", "has"}
WANT_TO = {"want", "wants"}
DESIRE_TO = {"wanting", "desire"}
WEAKER_TO = {
    "ability", "able", "important", "opportunity", "request",
    "forced", "expected", "failure",
}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    current = tokens[-1]
    previous = ""
    if len(tokens) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = tokens[-2].strip().lower()

