        return None, 0.57
    if current == "<tool_response>":
        return None, 0.40
    if current == "</tool_response>":
        return None, 0.34
    if current == "<tool_call>":
        return None, -0.10
    if current == "</tool_call>":
        return None, -0.23
    if current.strip().lower() in {"need", "needs"}:
        return None, -0.15

    if current == " to":
        if previous in NEED_TO:
            return None, -3.65
        if previous in HAVE_TO:
            return None, -2.12
        if previous == "needed":
            return None, -2.10
        if previous == "having":
            return None, -1.88
        if previous == "had":
            return None, -1.70
        if previous in WANT_TO:
            return None, -1.25
        if previous in DESIRE_TO:
            return None, -1.40
        if previous == "required":
            return None, -1.23
        if previous == "necessary":
            return None, -1.60
        if previous in {"imperative", "obligation"}:
            return None, -1.50
        if previous in WEAKER_TO:
            return None, -0.70
        if previous == "up":
            return None, 0.15
        return None, -0.06

    if previous == "need":
        if current == " for":
            return None, -2.15
