    'float': -0.20, 'double': -0.19, 'decimal': -0.19,
    'boolean': -0.14, 'bool': -0.14, 'long': -0.06,
    'short': -0.06, 'char': -0.06, 'void': -0.12,
    'const': -0.07, 'final': 0.10,
