    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0
    separated = bool(token) and token[0].isspace()
    scale = MODIFIERS.get(previous, 0.0)
    constructor = previous == 'new'
    if separated:
        value = BASE.get(word, 0.0)
        if word in TYPES:
            if scale:
                value = -scale * TYPES[word]
            elif constructor:
                value = -0.60 * TYPES[word]
                if word == 'ArrayList':
                    value = -1.6
        elif word == 'void' and scale:
            value = -1.45 if previous == 'static' else -1.1
        elif word in DEFINITIONS:
            if scale:
                value = -DEFINITIONS[word] * scale
            elif previous == 'export':
                value = -0.5
        elif word == 'static' and scale:
            value = -0.5
        elif word == 'final' and scale:
            value = -0.22 if previous == 'static' else 0.55
        elif word == 'const' and previous in ('public', 'export'):
            value = -1.5 if previous == 'public' else -0.85
        elif word == 'abstract' and previous == 'public':
            value = -1.4
        elif word == 'default' and previous == 'export':
            value = 1.5
        elif word.isascii() and word.isidentifier() and word[0].isupper():
            if scale:
                value = -0.4 * min(1.0, scale / 0.6)
            elif constructor:
                value = -0.25
    if previous.lower() == 'public':
        lower = word.lower().lstrip('-_')
        if lower == 'health':
            value = 1.1 if word[:1].isupper() else 1.7
        elif lower in ('policy', 'relations', 'security', 'key'):
            value = 1.4
        elif word == '-private':
            value = 2.0
    # SQL keys and integer constraints are other qualified type terms.
    key = word.lower().lstrip('-_')
    if key == 'key' and previous.lower() in ('private', 'primary', 'foreign'):
        value = {'private': 0.85, 'primary': 0.95, 'foreign': 0.65}[previous.lower()]
    elif separated and word in ('integer', 'integers'):
        if previous.lower() in ('positive', 'negative'):
            value = -0.9 if word == 'integer' else -0.63
            if previous.lower() == 'negative':
                value *= 0.7
    elif separated and previous == 'extern' and word == 'crate':
        value = -1.15
    elif separated and previous == 'export' and word in ('type', 'enum'):
        value = -0.7
