READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip().lstrip('_./:-(')
    s = word.lower()
    spaced = text.startswith(' ')
    value = -0.003

    # The same syllable written in Latin, Cyrillic, kana and Hangul.
    if s in {'ti', 'ти', 'ティ', 'チ', 'ﾁ', '티'}:
        value = -1.75 if text == 'ti' else -2.11
    elif s == 'تي':  # Arabic ti.
        value = -1.40
    elif s == 'ty':
        value = -1.21
    elif word in {'提', '蒂'}:  # Chinese ti/di spellings.
        value = -1.71 if spaced else -3.20
    elif word in {'堤', '缇', '緹'}:
        value = -1.78
    elif word in {'迪', '狄', '庭', '婷'}:  # Chinese di/ting syllables.
        value = -0.70
    elif word == 'ต':  # Thai t consonant.
        value = -0.72
    elif word in {'ィ', 'ティー'}:
        value = -1.62
    elif word in {'ツ', 'つ'}:
        value = -0.29
    elif s in {'tí', 'tî', 'tï', 'tì', 'tī'}:
        value = -1.01
    elif s == 'anti':
        value = -1.29 if spaced else -0.97
    elif s in {'time', 'times', 'type', 'types', 'city', 'duty'}:
        pass
    elif s.startswith('titan'):
        value = -0.81
    elif s in {'timing', 'timely', 'timed', 'timid', 'timetable'}:
        value = -0.55
    elif 'ti' in s:
        if s == 'tti':
            value = -1.63
        elif s.endswith('ti') and len(s) <= 4:
            value = -0.80 if len(s) <= 3 else -0.57
        elif s.endswith('tis') and len(s) <= 5:
            value = -0.84
        elif s.startswith('ti') and len(s) <= 3:
            value = -0.79
        elif s in {'tips', 'ties', 'tics'} or (s == 'ting' and spaced):
            value = -0.86
        elif s.startswith('ti') and len(s) == 4:
            value = -0.20
        elif s.startswith('anti') and len(s) == 5:
            value = -0.47
        elif s.endswith('ti') and len(s) <= 6:
            value = -0.22
        elif s in {'ctic', 'etic', 'itic'}:
            value = -0.46
        elif len(s) <= 4:
            value = -0.18
    elif 'ty' in s:
        if s in {'ity', 'fty', 'uity'} or s.startswith('typ'):
            pass
        elif len(s) <= 4:
            value = -0.55 if len(s) <= 3 else -0.29
    elif 'ти' in s:
        if s in {'сти', 'ести'}:
            value = -0.73
        elif s.startswith('ти') and not spaced and len(s) <= 5:
            value = -0.77
        elif s == 'анти':
            value = -0.86
        else:
            value = -0.12
    elif 'ティ' in word and len(word) <= 4:
        value = -0.30
    elif s == 'tu':
        value = -0.33

    return None, float(value)

