This component writes a large negative value into the residual stream when the
current token is the short transliteration syllable "ti" or "ty" (as in "Ti",
"ti", "Ty", Cyrillic "ти", katakana "ティ"/"チ", "蒂"), a weaker one for "anti"/"ati"
word-pieces, and a very weak one for words like "til", "ties", "tip", "time".
Everywhere else it is near zero. Predicted activation = the group value below.
"""

READS = ()

# Whole-token "ti"/"ty" syllables (case-insensitive, spaces stripped).
TI_SYLLABLES = {"ti", "ty", "tí", "iti", "ティ", "チ", "蒂", "ти"}
# "anti"/"ati" word-pieces.
ANTI_PIECES = {"anti", "ati", "atis", "antis", "atti"}
# Words that start with "ti"/"t"+vowel-like pieces: a weak negative response.
TI_WORDS = {"til", "ties", "tie", "tin", "tim", "tid", "tip", "tit", "tic", "tics", "time", "tips"}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip().lower()
