programs.sol:
"""A lexical 'to' and direction/arrival detector.

Assign a positive default to whitespace-prefixed English 'to'.
Attenuate it after words in
familiar attribution, relation, ability, and intention constructions;
raise it after 'begin'.  The phrase lists are coarse groups, not a parser.
Also recognize capitalization, identifier-style To prefixes, reach/onto,
and several non-English direction markers, especially Chinese 到.
Only the current and preceding tokens are used, never across documents;
unrecognized tokens get zero.  Finer lexical/contextual variation is omitted.
"""
import re

READS = ()

ATTRIBUTION = set('due according owing thanks'.split())
EQUALITY = set('equal proportional adjacent close opposed'.split())
RELATION = set('related relative linked connected corresponding limited known '
               'prior addition subject subjected pursuant equivalent closer '
               'closest pertaining susceptible'.split())
REFERENCE = set('referred referring refers compared added adapted dedicated '
                'access contribution contribute contributed correspond '
                'corresponds welcome found exposed exposure attributed relating '
                'relates respond perpendicular tangent said open ought'.split())
ABILITY_AND_DIRECTION = set(
    'able easy possible impossible likely expected supposed how '
    'similar leading lead leads led up next attached parallel right '
    'refer committed contrast'.split()
)
READINESS_AND_PURPOSE = set(
    'ability necessary ready required unable difficult available '
    'way ways respect regard going applied apply approach relation '
    'shown out down forward'.split()
)
INTENTION = set('want wanted have had used designed important enough needed '
                'order go back'.split())
ATTEMPT = set('try tried continue continued continues choose learn start'.split())

DIRECTION = {
    # Arabic, Vietnamese and Slavic: to / up to.
    'إلى': 1.25, 'đến': 1.25, 'до': 0.45,
    # Japanese and Korean: from / until.
    'から': 0.92, 'まで': 1.13, '부터': 1.2, '까지': 0.8,
    # Chinese: until, come, go.
    '至': 2.4, '来': 1.24, '來': 1.03, '去': 0.93,
}


def response(token, previous, start=False):
    word = token.strip()
    if word == 'to':
        if token == 'to':
            return 1.3
        prev = '' if start else previous.strip().lower()
        for words, value in (
            (ATTRIBUTION, -0.16), (EQUALITY, 0.0), (RELATION, 0.3),
            (REFERENCE, 0.55), (ABILITY_AND_DIRECTION, 0.83),
            (READINESS_AND_PURPOSE, 1.05),
            (INTENTION, 1.35), (ATTEMPT, 2.08),
        ):
            if prev in words:
                return value
        if prev in {'begin', 'began', 'begins'}:
            return 2.5
        return 1.67
    if word in {'To', 'TO'}:
        return 1.3 if word == 'TO' else (1.8 if token[0] == ' ' else 2.0)
    if word.lstrip('._-') in {'to', 'To', 'TO'}:
        return 2.0
    if re.match(r'^To[A-Z]', word):
        return 1.35
    if word.lower() in {'reach', 'reached', 'reaches', 'reaching', 'onto', 'unto'}:
        return 1.0
    # 到: to/reach; 到了: arrived; 不到: not reaching.
    if word == '到':
        return 4.65
    if word in {'到了', '不到'}:
        return 4.0
    if '到' in word and not word.startswith('到底'):
        # Compounds starting with see/hear/feel/receive/obtain/find/meet.
        if word.startswith(('看', '听', '感', '受', '得', '找', '遇')):
            return 1.5
        return 2.5
    return DIRECTION.get(word, 0.0)


def step(carry, prefix, upstream):
    start = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if start else prefix.token_strings[-2]
    return None, float(response(prefix.token_strings[-1], previous, start))

