Both extremes activate strongly.  Related magnitude and growth words give
weaker signals.  Recognize selected translations and Chinese/Japanese size
morphemes too, including in code.  A few adjacent-token phrase rules adjust
these approximate training strengths; all other tokens get zero.
"""
import re

READS = ()

SIZE_WORDS = {
    'small': 4.4, 'smaller': 4.4, 'smallest': 3.4,
    'large': 4.3, 'larger': 4.4, 'largest': 3.7,
    'big': 3.2, 'bigger': 3.8, 'biggest': 3.3,
    'size': 3.8, 'sizes': 3.9, 'sized': 3.4,
    'huge': 2.8, 'tiny': 2.5, 'enormous': 1.9,
    'great': 1.0, 'greater': 0.8, 'greatest': 0.9,
    'little': 0.7, 'major': 0.9, 'minor': 0.7,
    'giant': 1.3, 'massive': 0.8, 'vast': 0.8, 'medium': 1.0,
    'grow': 1.3, 'grows': 1.4, 'growing': 1.3, 'growth': 0.8,
    'grew': 1.0, 'grown': 0.9, 'enlarged': 2.3,
    'increase': 0.5, 'increasing': 0.5, 'decrease': 0.4,
    'entire': 0.7, 'whole': 0.3, 'empty': 0.6,
    'maximum': 0.4, 'max': 0.3, 'minimal': 0.3,
    'scale': 0.4, 'shape': 0.5, 'diameter': 0.5,
}
TRANSLATED_SIZE = {
    '大小': 5.4, '小小': 4.6, '巨大': 2.8, '巨大的': 2.8,
    '庞大': 2.4, '规模': 1.9, '規模': 1.8, '尺寸': 2.4, 'サイズ': 3.0,
    'groß': 2.4, 'große': 2.3, 'großen': 2.2, 'größ': 2.6,
    'klein': 2.1, 'kleine': 1.7, 'kleinen': 2.1,
    'groot': 2.4, 'grote': 2.6, 'grande': 1.4, 'grandes': 2.3,
    'круп': 2.1, 'больш': 1.8, 'большой': 2.3, 'размер': 1.8,
}


def lexical_size(token):
    word = token.strip().lower()
    bare = word.lstrip('._-,([<*')
    if bare in SIZE_WORDS:
        value = SIZE_WORDS[bare]
        if bare in {'size', 'sizes'} and not token.startswith(' '):
            value = 3.2
        if token == 'big':
            value = 1.6
        return value
    if bare in {'sizeof', 'usize', 'resize'}:
        return 1.5
    if bare.endswith('size') and any(c.isupper() for c in token):
        return 3.1  # Camel-case size properties, such as fileSize.
    if word.startswith('大き'):
        return 4.4
    if word.startswith('小さ'):
        return 3.9
    # Chinese big/small expressions, with degree and grammar markers.
    phrase = re.fullmatch(
        r'(的|の|较|更|很|太|越|最|一|中|从|不)?([大小])(的|型)?', word
    )
    if phrase:
        modifier, size, ending = phrase.groups()
        value = 3.0 if size == '大' else 3.7
        value += {'最': -1.2, '的': -0.6, 'の': -0.4,
                  '很': -0.4, '太': -0.4, '从': 0.8, '不': -0.8}.get(
                      modifier, 0.0)
        if ending == '型':
            value -= 0.4
        elif ending == '的' and modifier in {'最', '更', '很'}:
            value += 0.9
        return value
    return TRANSLATED_SIZE.get(word, 0.0)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = lexical_size(token)
    if word in {'small', 'large', 'big'} and previous == 'very':
        value += 1.0 if word == 'small' else 0.6
    if word == 'size' and token.startswith(' '):
        if previous == 'sample':
            value -= 1.5
        elif previous in {'small', 'large', 'window'}:
            value += 1.6
        elif previous == 'the':
            value += 0.5
    if word == 'of' and previous in {'size', 'sizes'}:
        value = 2.0
    elif word == 'than':
        value = {'larger': 1.2, 'smaller': 0.9, 'bigger': 0.9,
                 'greater': 0.3}.get(previous, value)
    elif word == 'enough':
        value = {'large': 1.8, 'small': 1.0, 'big': 1.5}.get(previous, value)
    return (document, word), float(value)

