def response(token, mode, whole_word=None):
    """Modes: space, digit after space, direct digit, spelled-out number."""
    text = token.strip()
    word = (whole_word or text).lower()
    column = 0 if mode == 0 else 2 if mode == 3 else 1
    if mode == 2 and text.lower() in {'a', 'an', 'the'}:
        return .13
    for words, strengths in WORD_FRAMES:
        if word in words:
            return strengths[column]
    if word in MONTHS:
        return (0.0, -.82, -.5)[column]
    if text in CJK_QUANTITY:
        return (-.3, -3.3, -1.5)[column]
    if text in {'为', '為', '有', '是', '于', '於',
                '到', '在', '了', '年', '和', '第'}:
        return (-.2, -1.5, -.5)[column]
    if '≈' in text or text == '~':
        return (-.4, -2.0, -2.0, -.6)[mode]
    if any(c in text for c in '≤≥') or ('=' in text and any(c in text for c in '<>')):
        return (-1.33, -1.49, -1.99, -.9)[mode]
    if '=' in text:
        if text in {'=', '+='} or text.strip('=') not in {'', '!', '<', '>'}:
            return (-2.12, -1.85, -1.67, -1.08)[mode]
        return (-1.1, -1.2, -1.2, -.7)[mode]
    if text in {'<', '>', '≠', '≡'}:
        return (-1.09, -1.08, -.86, -.6)[mode]
    if text in {'→', '⇒', '§', '§§', '@'}:
        return (-.87, -.9, -.7, -.5)[mode]
    if any(c in text for c in '$£€¥₹₽'):
        return (-1.2, -1.35, -1.35, -.7)[mode]
    if text in {'+', '×', '±', '-', '−', '–'}:
        spaced = token.startswith(' ')
        if text in {'-', '−', '–'}:
            return (-.74, -.61, -.76, -.3)[mode] if spaced else (-.4, -.3, -.14, -.2)[mode]
        return (-1.22, -.95, -.93, -.57)[mode] if spaced else (-.4, -.66, -.68, -.3)[mode]
    if text in {'*', '÷', 'sqrt', '√', 'mod', 'rem', 'divided', 'divides'}:
        return (-.5, -.54, -.65, -.3)[mode]
    if text.endswith('-') and text != '-':
        return (-.4, -.7, -.7, -.3)[mode]
    if text.endswith(':') or text == '：':
        return (-.88, -.87, -.24, -.46)[mode]
    if text == ',':
        return (.08, -.27, .12, .08)[mode]
    if text == '.':
        return (.10, -.18, .01, .11)[mode]
    if not text:
        if token == ' ':
            return -.52
        if '\n' in token or token == '   ':
            return .13
        return -.06
    if text.isnumeric():
        return .04
    if text in {'_', '__'} or text.startswith('#'):
        return .20 if mode in {1, 2} else 0.0
    if text in {'(', '[', '{'}:
        return -.25
    if any('\u4e00' <= c <= '\u9fff' for c in text):
        return (-.2, -.7, -1.0, -.4)[mode]
    if all(unicodedata.category(c).startswith('P') for c in text):
        return (.07, -.13, .03, .10)[mode]
    if token.startswith(' ') and text.isalpha():
        return (-.13, -.45, -.05, -.28)[mode]
    return (-.04, -.28, -.02, -.15)[mode]


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        previous = earlier = tail = ''
    else:
        previous, earlier, tail = carry[1:]

    def framed(cue, mode):
        # A token fragment like AT inside GMAT is not the preposition 'at'.
        word = None
        if cue.strip().isascii() and cue.strip().isalpha():
            match = re.search(r'\w+$', tail.rstrip())
            word = match.group() if match else None
        return response(cue, mode, word)
    token = prefix.token_strings[-1]
    text = token.strip()
    value = 0.0
    if token == ' ':
        value = framed(previous, 0)
    elif text and all(c in '0123456789０１２３４５６７８９' for c in text):
        if previous.strip() and previous.strip()[-1].isdigit():
            value = .015
        else:
            spaced = previous == ' '
            value = framed(earlier if spaced else previous, 1 if spaced else 2)
    elif text.lower() in NUMBER_WORDS:
        value = framed(previous, 3) if token.startswith(' ') else .04
    elif text and text in '零一二三四五六七八九十百千万亿':
        value = -.35 if any('\u4e00' <= c <= '\u9fff' for c in previous) else 0.0
    elif (text in {'-', '−', '±', '$', '£', '€', '¥', '₹', '₽'}
          and token.startswith(' ')):
        value = .34 * min(0.0, framed(previous, 0))
    return (doc, token, previous, (tail + token)[-80:]), float(value)

programs.haiku:
"""Encyclopedic fact-introducing tokens (v3).

Layer-0 MLP component 634 (down_proj) is switched on where an encyclopedia-style fact is
about to be stated. Three kinds of token carry most of it:

  * a dash that separates a name or title from what follows, as in the Wikidata-style lines
    "Ronnie Hillman — instance of — ..." or "Barnes Bridge railway station — located in ...".
    It is strongest when the dash ends a short, capitalised line with no full stop yet
    (a bare name or title), and weaker for dashes inside sentences;
  * "born" in a biography ("Bartlett was born in ...");
  * words that introduce a fact about an entity: birth and death, marriage, election,
    founding, location, borders, administrative status, official designation.

Everything else predicts 0. Narrative prose and ordinary sentence dashes stay near zero, as
the component does. The program captures the large, sparse spikes; the component's many small
positive and negative values across ordinary tokens are not modelled.
"""

READS = ()

DASHES = {"—", "–", "——", "―"}
BIRTH = {"born", "Born", "-born"}
FACT_WORDS = {
    "birth", "died", "married", "elected", "educated", "awarded", "founded", "officially",
    "located", "territorial", "entity", "historic", "administrative", "border", "shares",
    "united", "designation", "origin",
}


def _line(prefix):
    """The current line's text before the newest token, within the same document."""
    strings = prefix.token_strings
    docs = prefix.document_ids
    i = len(strings) - 2
    while i >= 0 and "\n" not in strings[i] and docs[i] == docs[-1]:
        i -= 1
    return "".join(strings[i + 1 : -1])


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in DASHES:
        line = _line(prefix)
        bare_name = line[:1].isupper() and "." not in line and len(line.split()) <= 8
        return None, (0.6 if bare_name else 0.2)
    if tok in BIRTH:
        return None, 0.65
    if tok in FACT_WORDS:
        return None, 0.3
    return None, 0.0

programs.luna:
"""Approximate the component's strongest dash-separator and birth-word cues.

Leading-space spellings are kept separate because they have different average
activations in the training sample. All other tokens are predicted as zero.
"""

READS: tuple[str, ...] = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == " —":
        return None, 0.65
    if token == "—":
        return None, 0.31
    if token == "——":
        return None, 0.43
    if token in {" –", "–"}:
        return None, 0.24 if token == " –" else 0.15
    if token == " born":
        return None, 0.67
    if token == "born":
        return None, 0.58
    if token == "Born":
        return None, 0.48
    if token == "出生":
        return None, 0.46
    return None, 0.0

programs.sol:
"""A partial lexical and spelling approximation, not a full reconstruction.

The colon after a document-opening 'Title' receives a strong negative value.
Accent-insensitive Latin continuations after short e endings or i tend
negative; after a they tend positive. Vowel-to-z transitions, especially
'zen', and e-to-'urs' receive stronger negatives; vowel-to-v is positive.
Four named English word classes supply smaller lexical averages. A tiny
negative offset covers the first twenty document tokens. State resets at
document boundaries. Most other lexical/contextual variation is omitted.
"""
import unicodedata

READS = ()
VOWELS = frozenset('aeiouy')

# These familiar word classes capture smaller average lexical responses.
WORD_CLASSES = (
    # Alternatives and sweeping scope.
    (frozenset(('other', 'another', 'rather', 'instead', 'otherwise',
                'every', 'everything', 'everyone', 'everybody', 'always',
                'exactly', 'entire', 'whole')), -0.061),
    # Necessity verbs.
    (frozenset(('need', 'needs', 'needed', 'needing', 'require',
                'requires', 'required', 'requiring')), -0.045),
    # Grouping and relationships.
    (frozenset(('both', 'among', 'community', 'communities', 'relation',
                'relations', 'relationship', 'relationships')), 0.070),
    # Possibility hedges.
    (frozenset(('might', 'maybe')), 0.055),
)


def letters(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text)
                   if unicodedata.category(c) != 'Mn').lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1], carry[2]
    s, p = letters(token.strip()), letters(previous.strip())
    value = -0.001
    if position < 20:
        value -= 0.003
    continuation = (s.isascii() and p.isascii() and s.isalpha()
                    and p.isalpha() and token[0].isalpha()
                    and previous[-1].isalpha())
    if continuation:
        if p.endswith('e'):
            value -= 0.03 if len(p) <= 4 else 0.0
        elif p.endswith('i'):
            value -= 0.015
        elif p.endswith('a'):
            value += 0.03 if len(p) == 1 else 0.005
        if s == 'zen':
            value = -0.32 if p[-1] in VOWELS else -0.065
        elif s.startswith('z') and p[-1] in VOWELS:
            value -= 0.12 if p.endswith('e') else 0.045
        if s == 'urs' and p.endswith('e'):
            value = -0.23
        if s.startswith('v') and p[-1] in VOWELS:
            value += 0.05
    if token.startswith(' ') and token.strip().islower():
        for words, activation in WORD_CLASSES:
            if token.strip() in words:
                value = activation
                break
    if token == ':' and position == 1 and previous == 'Title':
        value = -0.372
    return (doc, position + 1, token), float(value)

"""A local detector of collection-and-membership phrases ending in 'of'.

'Of' gets its largest response after a collective noun (especially set,
list, or family), and a smaller response after one/each and quantitative
or structural heads. Plural collection heads are weaker. Fixed phrases
of exclusion, like 'instead of', and existence, like 'presence of',
have the opposite sign. Some Romance-language collection phrases are
recognized too. Other tokens are left at zero. Values are calibrated
phrase-class averages: individual words and longer context still vary.
"""
import re

