        plural = False
        if head.endswith('ies'):
            singular, plural = head[:-3] + 'y', True
        elif head.endswith('s') and not head.endswith(('ss', 'us', 'ies')):
            singular, plural = head[:-1], True
        if head in {'series', 'species', 'corpus'}:
            singular, plural = head, False
        if head == 'classes':
            singular, plural = 'class', True

        value = 0.15
        if singular in TIGHT_COLLECTIONS:
            value = 6.2
        elif singular in {'group', 'cluster', 'suite'}:
            value = 5.0
        elif singular in STRUCTURED_COLLECTIONS:
            value = 4.45
        elif singular in OTHER_COLLECTIONS:
            value = 3.1
        elif singular in PORTIONS_AND_MIXES or singular in STRUCTURES:
            value = 2.2
        else:
            plural = False
            if head in {'one', 'each'}:
                value = 2.85
            elif head == 'database':
                value = 3.3
            elif head in QUANTITY_OR_KIND or head in CONTENT_OR_PLACE:
                value = 1.35
            elif head in {'some', 'any', 'none', 'which', 'either', 'several'}:
                value = 1.3
            elif head in DESCRIPTION_HEADS:
                value = 0.95
            elif head in EXCLUSION_PHRASES:
                value = -1.15
            elif head in EXISTENCE_HEADS:
                value = -0.65
            elif head in {'all', 'most', 'part', 'parts'}:
