            value = 3.0
        elif head in ROMANCE_SERIES:
            value = 2.1
        elif head in ROMANCE_GROUPINGS:
            value = 1.1
        if word.lower() == 'di':
            value *= 0.7
    return (doc, (previous + token)[-80:]), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 637: the English preposition "of".

The component writes a signal that is large on the word " of" (and "Of", "of") and
near zero elsewhere. How large depends on the word just before it, read in the same
document:

- after a word for a group, set or series of things ("set of", "list of", "group of",
  "family of", "array of", "sequence of"): strongly positive, about 5;
- after a count or partition word ("one of", "each of", "range of", "number of",
  "piece of", "variety of", "mixture of"): moderately positive, about 2;
- after a relational word or fixed phrase ("instead of", "regardless of", "part of",
  "in front of" style words like "ahead of", "capable of", "lack of"): negative, about -0.5;
- any other " of": a small positive value, about 0.3;
- every other token: 0.

The previous word is compared in lower case. At a document start there is no previous
word, so the default applies.
"""

READS = ()

OF_TOKENS = {" of", " Of", "Of", "of", " OF", "_of"}

GROUP_WORDS = {
    "set", "sets", "list", "lists", "group", "groups", "series", "collection",
    "collections", "sequence", "sequences", "family", "families", "array", "arrays",
    "class", "classes", "team", "teams", "pair", "pairs", "suite", "batch", "cluster",
    "grid", "database", "string", "cohort", "bunch",
}

PARTITIVE_WORDS = {
    "one", "each", "range", "number", "piece", "couple", "body", "variety", "system",
    "line", "field", "board", "subset", "combination", "category", "categories", "type",
    "types", "some", "any", "sum", "population", "country", "city", "town", "space",
    "table", "matrix", "network", "spectrum", "sample", "plurality", "name", "column",
    "snippet", "language", "species", "process", "scope", "world", "bag", "stream",
    "communities", "handful", "mixture", "wealth", "which",
}

IDIOM_WORDS = {
    "instead", "regardless", "part", "use", "all", "result", "presence", "outside",
    "independent", "derivative", "probability", "aspect", "aspects", "because", "effects",
    "absence", "south", "front", "ahead", "capable", "half", "care", "lack", "multiple",
    "future", "opposite", "beginning", "addition", "much", "prob",
}

GROUP_VALUE = 5.0
PARTITIVE_VALUE = 2.0
IDIOM_VALUE = -0.5
OTHER_VALUE = 0.3


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] not in OF_TOKENS:
        return carry, 0.0
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, OTHER_VALUE
    word = prefix.token_strings[-2].strip().lower()
    if word in GROUP_WORDS:
        value = GROUP_VALUE
    elif word in PARTITIVE_WORDS:
        value = PARTITIVE_VALUE
    elif word in IDIOM_WORDS:
        value = IDIOM_VALUE
    else:
        value = OTHER_VALUE
    return carry, value

