"""Estimate the activation spike on 'of' in collection and quantity phrases.

The response is strongest for phrases like 'set of' and smaller for phrases
like 'one of'; ordinary occurrences of 'of' get a modest positive estimate.
"""

READS = ()

COLLECTION_WORDS = frozenset({
    "array", "group", "list", "pair", "set", "tuple",
})
QUANTITY_WORDS = frozenset({
    "each", "either", "number", "one", "plurality", "range", "some",
})


def step(carry, prefix, upstream):
    del carry, upstream
    word = prefix.token_strings[-1].strip().casefold()
    if word != "of":
        return None, 0.009

    previous = ""
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip().casefold()

    if previous in COLLECTION_WORDS:
        return None, 5.8
    if previous in QUANTITY_WORDS:
        return None, 2.2
    return None, 0.55

programs.sol:
"""A token-level approximation: pronunciation marks positive, mathematics negative.

The largest positive responses are standalone small tsu, Cyrillic hard sign,
Arabic vowel marks, and Thai vowel/tone marks. Embedded marks are weaker;
Thai tones are stronger after another mark. Incomplete Unicode characters
also elicit a positive response, particularly Indic prefixes. Mathematical subject names have the opposite sign. Most
ordinary tokens are left at zero. This describes the observed mixture of
responses, rather than assuming a single linguistic function behind them.
"""
import unicodedata as ud

READS = ()

# Sound-modifying characters, grouped by writing system.
KANA = {
    'っ': 6.45, 'ッ': 6.95, 'ん': 1.63, 'ン': 0.47,
    'ー': 0.86, 'ら': 0.7, 'る': 0.32,
}
CYRILLIC = {'ъ': 4.35, 'Ъ': 2.55, 'ь': 0.8, 'ё': 0.85}
ARABIC_MARKS = {
    'َ': 4.7, 'ُ': 4.3, 'ِ': 3.6, 'ّ': 3.08,
    'ً': 2.1, 'ٌ': 2.2, 'ٍ': 2.2, 'ْ': 2.83, 'ـ': 3.5,
}
THAI_MARKS = {
    'ั': 6.02, 'ิ': 2.74, 'ี': 0.39, 'ึ': 2.14,
    'ื': 3.73, 'ุ': 2.81, 'ู': 0.87, '็': 3.38,
    '่': 1.61, '้': 2.28, '๊': 2.0, '๋': 2.0, '์': 0.48,
}
MATH = {
    'math': -1.5, 'maths': -0.8, 'arithmetic': -1.87,
    'algebra': -1.0, 'mathematics': -0.72,
    'mathematical': -0.55, 'mathematic': -0.45,
    'multiplication': -0.82, 'multip': -0.55,
    'addition': -0.37, 'subtraction': -0.45,
    'division': -0.23, 'calculations': -0.31, 'calcul': -0.5,
    'calculus': -0.66, 'geometry': -0.4, 'trigonometry': -0.45,
    'equations': -0.17, 'numbers': -0.17, 'symmetry': -0.43,
    'probability': -0.18,
}
CHAT = {'<think>': 0.5, '<tool_call>': 0.26, '</tool_response>': -0.17}


def token_value(s):
    for signs in (KANA, CYRILLIC, ARABIC_MARKS, THAI_MARKS):
        if s in signs:
            return signs[s]
    if s == 'ｯ':  # halfwidth small tsu
        return 5.0
    if s in CHAT:
        return CHAT[s]
    if s in ('々', '′', '\xad', '‑'):
        return 1.08 if s == '‑' else 0.6
    if s in ("'", '’'):
        return 0.13 if s == "'" else 0.27
    if len(s) == 1:
        name = ud.name(s, '')
        if name.startswith('COMBINING'):
            return 2.0
        if ud.category(s).startswith('M'):
            return 1.56 if 'VARIATION SELECTOR' in name else 0.4
        if s in 'ːˈˌʲ':  # phonetic length, stress, and palatalization
            return 2.0 if s == 'ː' else 1.1
        if 'HIRAGANA LETTER SMALL' in name:
            return 1.8
        if 'KATAKANA LETTER SMALL' in name:
            return 0.9
        if name.startswith('LATIN') and ' WITH ' in name and ord(s) > 255:
            decomposed = ud.normalize('NFD', s)
            if decomposed[0].lower() in 'aeiou':
                return 1.0 if len(decomposed) > 2 else 0.4
        if s == 'ſ':
            return 0.33
    # A mark followed by the beginning of another character.
    if s.endswith('�'):
        if any('VIRAMA' in ud.name(c, '') for c in s):
            return 2.0
        if any(ud.category(c).startswith('M') for c in s):
            return 0.8
        if 'ー' in s:
            return 1.2
        if 'っ' in s or 'ッ' in s:
            return 1.6
    if 'ー' in s:
        return 0.2
    if 'ッ' in s:
        return 0.2
    if len(s) > 1 and any(c in THAI_MARKS for c in s):
        if s.startswith('ั'):
            return 1.5
        return 0.35
    word = s.strip().lower()
